// topic 16 – OSI & TCP/IP  (7E 8M 5H)
q(4,16,"How many layers does the OSI reference model have?",["4","5","6","7"],3,"The OSI model has 7 layers: Physical, Data Link, Network, Transport, Session, Presentation, Application.","easy");
q(4,16,"Which OSI layer is responsible for routing packets across multiple networks?",["Data Link","Transport","Network","Session"],2,"The Network layer (Layer 3) handles logical addressing (IP) and routing.","easy");
q(4,16,"Which layer converts data into raw bits for physical transmission?",["Data Link","Network","Transport","Physical"],3,"The Physical layer (Layer 1) transmits raw bits over a physical medium.","easy");
q(4,16,"In the TCP/IP model, which layer combines the OSI Session, Presentation, and Application layers?",["Internet layer","Transport layer","Application layer","Network Access layer"],2,"The TCP/IP Application layer corresponds to OSI Layers 5 (Session), 6 (Presentation), and 7 (Application).","easy");
q(4,16,"The PDU at the Data Link layer is called a:",["Packet","Frame","Segment","Bit"],1,"Data Link layer encapsulates network packets into frames that include MAC addresses and error-check fields.","easy");
q(4,16,"The PDU at the Transport layer is called a:",["Frame","Packet","Segment","Datagram"],2,"The Transport layer PDU is called a segment (TCP) or datagram (UDP).","easy");
q(4,16,"Which OSI layer provides end-to-end reliable data transfer, flow control, and error recovery?",["Network","Data Link","Session","Transport"],3,"The Transport layer (Layer 4) provides reliable (TCP) or unreliable (UDP) end-to-end communication.","easy");

q(4,16,"What is encapsulation in the context of network protocols?",["Compressing data before transmission","Each layer adding its own header (and sometimes trailer) to the data unit from the layer above","Encrypting data at the Physical layer","Multiplexing multiple data streams"],1,"Encapsulation: each layer adds control information (header/trailer) before handing the PDU to the next lower layer.","medium");
q(4,16,"The TCP/IP Internet layer corresponds most closely to which OSI layer?",["Data Link","Transport","Network","Session"],2,"The TCP/IP Internet layer handles IP addressing and routing, mirroring OSI Layer 3 (Network).","medium");
q(4,16,"Which device makes forwarding decisions based on IP addresses (Layer 3)?",["Hub","Switch","Router","Repeater"],2,"Routers examine IP headers and use routing tables to forward packets toward their destinations.","medium");
q(4,16,"What is the primary function of the OSI Presentation layer?",["Establishing and managing sessions","Translating data formats, handling encryption/decryption, and compression between application and lower layers","Routing packets across networks","Flow control between transport endpoints"],1,"The Presentation layer (Layer 6) handles data translation, encryption, and compression.","medium");
q(4,16,"A Layer-2 switch forwards frames based on:",["IP addresses","MAC addresses in its MAC address (CAM) table","Port numbers","Hostnames"],1,"Layer-2 switches use their MAC address table to forward frames to the correct port by destination MAC.","medium");
q(4,16,"What does ARP do?",["Resolves domain names to IP addresses","Maps IP addresses to MAC addresses on a local network","Routes packets between autonomous systems","Assigns IP addresses dynamically"],1,"ARP resolves a known IPv4 address to the corresponding MAC address for local Layer-2 delivery.","medium");
q(4,16,"The correct OSI layer order from lowest to highest is:",["Application, Transport, Network, Data Link, Physical","Physical, Data Link, Network, Transport, Session, Presentation, Application","Physical, Network, Data Link, Transport, Application","Network, Physical, Data Link, Transport, Application"],1,"1-Physical, 2-Data Link, 3-Network, 4-Transport, 5-Session, 6-Presentation, 7-Application.","medium");
q(4,16,"Which protocol resolves a hostname to an IP address?",["ARP","DHCP","DNS","RARP"],2,"DNS (Domain Name System) resolves FQDNs to IP addresses at the Application layer.","medium");

q(4,16,"A device strips the Layer-2 header, examines the Layer-3 packet, selects the next hop from its routing table, adds a new Layer-2 header, and forwards. This describes a:",["Hub","Layer-2 switch","Layer-3 router","Repeater"],2,"This is the router store-and-forward process: L3 decision, L2 re-encapsulation per outgoing link.","hard");
q(4,16,"IEEE 802.1Q VLAN tagging operates at which OSI layer and adds how many bytes to the Ethernet frame?",["Layer 3, 4 bytes","Layer 2, 4 bytes","Layer 4, 8 bytes","Layer 1, 2 bytes"],1,"802.1Q is a Layer 2 standard that inserts a 4-byte tag into the Ethernet frame to carry VLAN ID.","hard");
q(4,16,"TLS primarily operates at which TCP/IP model layer and spans which OSI layer functions?",["TCP/IP Application layer; spans OSI Presentation (encryption) and Session (handshake) layers","TCP/IP Transport layer; OSI Transport layer only","TCP/IP Internet layer; OSI Network layer","TCP/IP Network Access layer; OSI Physical and Data Link"],0,"TLS is implemented in the TCP/IP Application layer and provides services analogous to OSI Presentation and Session layers.","hard");
q(4,16,"The OSI Session layer's role that distinguishes it from the Transport layer is:",["Session provides reliable delivery; Transport does not","Session manages dialog control and synchronization checkpoints between applications; Transport handles end-to-end data delivery","Session encrypts data; Transport compresses it","They have identical functions"],1,"Session layer (5): establishes, manages, terminates sessions and handles dialog control/synchronization. Transport layer (4): end-to-end delivery.","hard");
q(4,16,"The TCP/IP model has 4 layers while OSI has 7 because:",["TCP/IP is incorrect and OSI is the only correct model","OSI is a conceptual reference with fine-grained layer separation; TCP/IP collapses some OSI layers (e.g., Application=OSI 5+6+7; Network Access=OSI 1+2) to reflect how Internet protocols are actually implemented","TCP/IP has additional layers not in OSI","OSI is newer and replaces TCP/IP"],1,"TCP/IP is a practical model derived from real Internet protocol design; OSI is a theoretical reference model with greater conceptual granularity.","hard");

// topic 17 – Routing  (7E 8M 5H)
q(4,17,"What does a routing table store?",["MAC addresses of connected devices","Network prefixes mapped to next-hop addresses and outgoing interfaces","Port-based filtering rules","Encryption keys for VPN tunnels"],1,"A routing table maps destination IP prefixes to next-hop routers or outgoing interfaces used for forwarding.","easy");
q(4,17,"Which routing metric does RIP use?",["Bandwidth","Hop count","Delay","Composite cost"],1,"RIP uses hop count (max 15; 16 = infinity/unreachable) as its sole metric.","easy");
q(4,17,"A default route (0.0.0.0/0) is used when:",["The packet is destined for the local subnet","No more specific route matches the destination IP","The route has the highest metric","The packet is a loopback"],1,"The default route is the catch-all forwarding entry when no more specific prefix matches.","easy");
q(4,17,"Which type of routing requires administrators to manually configure routes?",["Dynamic routing","Static routing","Default routing","Policy-based routing"],1,"Static routes are manually configured; they do not adapt automatically to topology changes.","easy");
q(4,17,"OSPF is classified as which type of routing protocol?",["Distance-vector","Path-vector","Link-state","Hybrid"],2,"OSPF is a link-state protocol: each router maintains a full topology map and runs Dijkstra's SPF algorithm.","easy");
q(4,17,"BGP is used for routing between:",["LANs within a single organization","Autonomous Systems (AS) on the Internet","Hosts within a subnet","VLANs in a data center"],1,"BGP is the Exterior Gateway Protocol used for inter-AS routing on the Internet.","easy");
q(4,17,"The 'longest prefix match' rule means:",["Choose the route with the fewest hops","Choose the route with the highest metric","Choose the routing table entry whose prefix matches the most bits of the destination IP","Always choose the default route"],2,"The most specific (longest matching prefix) routing table entry is selected for forwarding.","easy");

q(4,17,"Split horizon prevents routing loops by:",["Advertising routes only to the router that originally learned them","Never advertising a route back out through the interface from which it was learned","Splitting routing tables between two routers","Using different metrics on different interfaces"],1,"Split horizon: do not advertise a route back out the interface it was received on – prevents simple two-node loops.","medium");
q(4,17,"The 'count-to-infinity' problem in distance-vector protocols occurs when:",["Router tables grow too large","A route failure causes routers to iteratively increment their metric toward the configured infinity limit before declaring the route unreachable","Link-state databases are too large","Route summarization is misconfigured"],1,"After a link failure, distance-vector routers may bounce metric updates upward until reaching infinity (e.g., 16 in RIP).","medium");
q(4,17,"Administrative distance (AD) is:",["The number of hops to the destination","A trustworthiness metric assigned to each routing source; the route with the lowest AD is preferred when multiple protocols provide routes to the same destination","The link cost used by OSPF","The TTL placed in each packet header"],1,"AD ranks routing source reliability (static=1, OSPF=110, RIP=120). Lower AD wins when competing routes exist.","medium");
q(4,17,"OSPF computes shortest paths using:",["Bellman-Ford","Floyd-Warshall","Dijkstra's Shortest Path First (SPF)","Prim's algorithm"],2,"Each OSPF router runs Dijkstra's SPF on its link-state database to compute the shortest-path tree.","medium");
q(4,17,"Route Poisoning and Holddown timers help prevent:",["BGP route flapping","Routing loops in distance-vector protocols by advertising failed routes with metric=infinity and ignoring updates about them for a hold period","OSPF SPF storms","Packet fragmentation"],1,"Route poisoning (metric=infinity) and holddown timers reduce the risk of routing loops during topology convergence.","medium");
q(4,17,"On a broadcast network, OSPF elects a DR and BDR to:",["Perform NAT for the segment","Reduce flooding overhead: all routers form adjacencies only with DR/BDR instead of with every other router on the segment","Assign IP addresses via DHCP","Encrypt OSPF packets"],1,"DR/BDR election reduces OSPF adjacencies on broadcast segments from O(n²) to O(n), improving scalability.","medium");
q(4,17,"Route redistribution means:",["Backing up routing tables to a server","Importing routes learned by one routing protocol into another protocol's routing domain","Advertising all routes to all routers equally","Resetting routing tables to defaults"],1,"Redistribution enables inter-protocol routing (e.g., importing OSPF routes into BGP).","medium");
q(4,17,"Which BGP attribute contains the complete sequence of AS numbers a route has traversed?",["LOCAL_PREF","MED","AS_PATH","NEXT_HOP"],2,"AS_PATH lists every AS the route passed through; BGP prefers shorter AS_PATHs and uses it for loop prevention.","medium");

q(4,17,"OSPF Area 0 (backbone area) exists because:",["Area 0 performs NAT for the entire network","All inter-area traffic must pass through it; it is the transit area connecting all other OSPF areas","Area 0 is optional and used only for redundancy","Area 0 stores the complete routing table of the AS"],1,"OSPF hierarchical design mandates Area 0 as the hub: inter-area routes must flow through the backbone.","hard");
q(4,17,"IBGP vs. EBGP:",["IBGP runs between different ASes; EBGP runs within the same AS","EBGP runs between different ASes; IBGP runs within the same AS; IBGP does not increment AS_PATH and requires full mesh or route reflectors","They use different TCP port numbers","IBGP requires route reflectors; EBGP does not"],1,"EBGP crosses AS boundaries; IBGP is intra-AS. IBGP requires full-mesh or route reflectors because it does not re-advertise IBGP-learned routes to other IBGP peers.","hard");
q(4,17,"A 'black hole' route points traffic to:",["The next-hop router with the lowest metric","A discard (null) interface, silently dropping matching packets without sending ICMP Unreachable","A route learned via BGP with AS_PATH prepending","A route redistributed from RIP into OSPF"],1,"Black hole/null routes drop packets silently; used for traffic engineering and DDoS mitigation.","hard");
q(4,17,"EBGP sets TCP TTL to 1 by default to:",["Prevent routing loops","Limit EBGP sessions to directly connected peers; EBGP Multihop (TTL-security) overrides this for multi-hop EBGP sessions","Improve throughput","Set the standard TTL for all protocols"],1,"TTL=1 means only directly adjacent routers can form EBGP sessions, preventing spoofed BGP updates from distant hosts.","hard");
q(4,17,"SPF recalculation in OSPF is triggered by changes in the LSDB and its frequency is reduced by:",["Any frame received; 802.1Q VLAN tagging","Any LSDB change; SPF throttling with exponential backoff timers","Any BGP update; route reflectors","Any ARP cache expiry; GARP"],1,"SPF throttling with exponential backoff delays successive SPF runs during instability, protecting router CPU.","hard");

// topic 18 – IP Addressing  (7E 8M 5H)
q(4,18,"How many bits are in an IPv4 address?",["16","32","64","128"],1,"IPv4 addresses are 32-bit values written as four dotted-decimal octets.","easy");
q(4,18,"What is the IPv4 loopback address?",["0.0.0.0","255.255.255.255","127.0.0.1","192.168.0.1"],2,"127.0.0.1 (range 127.0.0.0/8) routes packets back to the same host for local testing.","easy");
q(4,18,"Which range is the Class C private IPv4 address space (RFC 1918)?",["10.0.0.0 – 10.255.255.255","172.16.0.0 – 172.31.255.255","192.168.0.0 – 192.168.255.255","169.254.0.0 – 169.254.255.255"],2,"RFC 1918 reserves 192.168.0.0/16 as private Class C address space, not routable on the public Internet.","easy");
q(4,18,"How many bits are in an IPv6 address?",["32","64","128","256"],2,"IPv6 addresses are 128-bit values written as eight groups of four hex digits separated by colons.","easy");
q(4,18,"In 192.168.1.0/24, the '/24' indicates that:",["There are 24 hosts","The first 24 bits form the network prefix","The subnet has 24 subnets","The last 24 bits are fixed"],1,"CIDR /24 notation: the first 24 bits are the network portion, leaving 8 bits for host addresses.","easy");
q(4,18,"A subnet mask is:",["An IPv6 address component","A 32-bit value ANDed with an IP address to separate the network and host portions","A MAC address format","A routing protocol metric"],1,"Subnet masks identify the network vs. host portions of an IP address.","easy");
q(4,18,"The broadcast address for 192.168.1.0/24 is:",["192.168.1.0","192.168.1.1","192.168.1.255","192.168.255.255"],2,"For a /24 subnet, all host bits set to 1 gives the broadcast address: 192.168.1.255.","easy");

q(4,18,"How many usable host addresses are in a /27 subnet?",["30","32","62","14"],0,"2^5 = 32 total; minus network and broadcast = 30 usable host addresses.","medium");
q(4,18,"Which ICMP type signals that a destination is unreachable?",["Echo Request (Type 8)","Echo Reply (Type 0)","Destination Unreachable (Type 3)","Time Exceeded (Type 11)"],2,"ICMP Type 3 (Destination Unreachable) is sent when a packet cannot be delivered.","medium");
q(4,18,"NAT's primary purpose is:",["Dynamically assigning IP addresses","Mapping private IP addresses to public IP addresses so multiple private hosts can share one or few public addresses","A routing algorithm for large networks","Subdividing subnets"],1,"NAT conserves public IPv4 address space and provides a boundary between private and public addressing.","medium");
q(4,18,"For 172.16.45.200 with mask 255.255.240.0, the network address is:",["172.16.0.0","172.16.32.0","172.16.45.0","172.16.48.0"],1,"255.255.240.0 = /20. Third octet: 240 AND 45 = 11110000 AND 00101101 = 00100000 = 32. Network: 172.16.32.0.","medium");
q(4,18,"VLSM (Variable Length Subnet Masking) allows:",["Using a fixed subnet mask for all subnets","Different subnets to use different prefix lengths within the same address space, optimizing address utilization","A method for assigning IPv6 addresses","A NAT technique for port translation"],1,"VLSM allocates subnet sizes matched to actual requirements, reducing wasted IPv4 address space.","medium");
q(4,18,"IPv6 address fe80::1/64 belongs to which address type?",["Global Unicast","Multicast","Link-Local Unicast","Loopback"],2,"FE80::/10 prefixes are IPv6 link-local unicast addresses, not routed beyond the local link.","medium");
q(4,18,"IPv6 uses which protocol instead of ARP for address resolution?",["RARP","DHCP","Neighbor Discovery Protocol (NDP)","IGMP"],2,"NDP (RFC 4861) uses ICMPv6 Neighbor Solicitation/Advertisement to replace ARP in IPv6.","medium");
q(4,18,"A /30 subnet provides how many total and usable addresses?",["4 total, 2 usable","2 total, 0 usable","8 total, 6 usable","6 total, 4 usable"],0,"2^2 = 4 total; minus network + broadcast = 2 usable – ideal for point-to-point router links.","medium");

q(4,18,"An organization needs 6 subnets each with at least 25 hosts from 200.200.200.0/24. The correct subnet mask is:",["255.255.255.192 (/26)","255.255.255.224 (/27)","255.255.255.240 (/28)","255.255.255.248 (/29)"],1,"/27 gives 8 subnets (2^3) each with 30 usable hosts (2^5-2). Both requirements satisfied: 8>=6 subnets, 30>=25 hosts.","hard");
q(4,18,"CIDR replaced classful addressing by:",["Using fixed class boundaries (A/B/C)","Allowing arbitrary-length network prefixes not tied to class boundaries, enabling precise allocation and route aggregation (supernetting) to reduce routing table size","Being an IPv6-only concept","Assigning addresses dynamically like DHCP"],1,"CIDR (RFC 1519) introduced variable-length prefixes, eliminating the waste of rigid 8/16/24-bit class boundaries.","hard");
q(4,18,"The summary route for 192.168.0.0/24, 192.168.1.0/24, 192.168.2.0/24, 192.168.3.0/24 is:",["192.168.0.0/22","192.168.0.0/23","192.168.0.0/21","192.168.4.0/22"],0,"These four /24s share the first 22 bits; the summary supernet is 192.168.0.0/22.","hard");
q(4,18,"EUI-64 generates a 64-bit IPv6 interface identifier by:",["Assigning a 32-bit network prefix","Splitting the 48-bit MAC address in two halves, inserting FF:FE between them, and flipping the Universal/Local bit","Compressing IPv6 headers","Providing IPv6 multicast addressing"],1,"EUI-64: split MAC at byte 3, insert FF:FE, invert bit 7 (U/L bit) of byte 1 to create a unique 64-bit IID.","hard");
q(4,18,"A router's table has: 10.0.0.0/8 via R1, 10.1.0.0/16 via R2, 10.1.5.0/24 via R3, 0.0.0.0/0 via R4. A packet for 10.1.5.67 goes to:",["R1","R2","R3","R4"],2,"Longest prefix match selects /24 (10.1.5.0/24) – the most specific matching entry – so R3.","hard");

// topic 19 – Transport Layer  (7E 8M 5H)
q(4,19,"The primary difference between TCP and UDP is:",["TCP is connectionless; UDP is connection-oriented","TCP provides reliable, ordered delivery with connection establishment; UDP provides fast, connectionless, best-effort delivery","UDP is always slower than TCP","TCP uses IP addresses; UDP uses MAC addresses"],1,"TCP: connection-oriented, reliable, ordered. UDP: connectionless, fast, best-effort.","easy");
q(4,19,"Which TCP port does HTTP use by default?",["21","23","80","443"],2,"HTTP uses TCP port 80; HTTPS uses TCP port 443.","easy");
q(4,19,"The TCP three-way handshake sequence is:",["SYN, ACK, SYN-ACK","SYN, SYN-ACK, ACK","ACK, SYN, FIN","FIN, SYN, ACK"],1,"TCP connection setup: Client → SYN; Server → SYN-ACK; Client → ACK.","easy");
q(4,19,"The TCP SYN flag is used to:",["Synchronize sequence numbers and initiate a connection","Acknowledge receipt of data","Terminate a connection","Reset the connection"],0,"SYN initiates a TCP connection and exchanges initial sequence numbers during the three-way handshake.","easy");
q(4,19,"DNS typically uses which transport protocol for standard queries?",["TCP only","UDP (port 53) for queries; TCP for zone transfers and large responses","ICMP","HTTP"],1,"DNS uses UDP port 53 for speed on small queries and TCP port 53 for zone transfers or responses >512 bytes.","easy");
q(4,19,"Port numbers in the transport layer are used to:",["Identify the physical network interface","Multiplex/demultiplex data streams by identifying specific application processes on a host","Determine the IP routing path","Specify encryption algorithms"],1,"Port numbers allow multiple applications on the same host to share the network simultaneously.","easy");
q(4,19,"UDP is commonly used for applications that require:",["Guaranteed delivery and ordering","Fast, low-latency transmission with acceptable loss (streaming media, DNS, VoIP)","Encryption at the transport layer","Retransmission of every lost packet"],1,"UDP trades reliability for low latency – suitable for applications that handle loss at the application layer.","easy");

q(4,19,"TCP flow control allows:",["Prevention of packet loss at the network layer","The receiver to control the sender's rate using the advertised window size to prevent buffer overflow","Prevention of network congestion across all routers","Encryption before transmission"],1,"The receiver's advertised window (rwnd) in ACKs tells the sender how much buffer space is available.","medium");
q(4,19,"TCP congestion control uses which algorithm when starting a new connection?",["AIMD only","Slow Start – exponential growth of cwnd from 1 MSS until ssthresh or a loss event","Selective Repeat","Round Robin"],1,"Slow Start doubles cwnd each RTT from 1 MSS until reaching ssthresh or detecting loss.","medium");
q(4,19,"The TCP sequence number field indicates:",["The source port number","The byte offset of the first byte in the segment's data within the byte stream","The number of segments sent","The TTL of the packet"],1,"TCP sequence numbers are byte-level counters; the sequence number identifies the first byte of the segment's payload.","medium");
q(4,19,"The TCP TIME_WAIT state exists to:",["Indicate an error state when the connection was reset","Allow the active-close side to wait 2*MSL so any delayed duplicate segments from the old connection expire before a new connection using the same 4-tuple is allowed","Wait during the initial handshake","Enter when no data is sent for 60 seconds"],1,"TIME_WAIT (2*MSL ≈ 60-120s) prevents old duplicate packets from corrupting a new connection with the same endpoints.","medium");
q(4,19,"TCP Selective Acknowledgment (SACK) allows:",["Out-of-order delivery","The receiver to acknowledge non-contiguous received blocks so the sender retransmits only the missing segments","Reduction of TCP header overhead","Negotiating connection parameters during handshake"],1,"SACK reports which out-of-order blocks arrived, enabling targeted retransmission of only the missing data.","medium");
q(4,19,"Well-known port numbers are in the range:",["0 – 1023","1024 – 49151","49152 – 65535","1024 – 65535"],0,"IANA defines well-known ports as 0-1023 (e.g., HTTP:80, SSH:22, HTTPS:443).","medium");
q(4,19,"The TCP FIN flag signals:",["An erroneous connection reset","The initiation of connection setup","The end of data transmission from one side (graceful close)","A request to retransmit lost segments"],2,"FIN indicates the sender has finished sending; TCP connection teardown uses a four-way FIN/ACK exchange.","medium");
q(4,19,"QUIC improves upon TCP+TLS by:",["Removing encryption for speed","Implementing reliable delivery, multiplexing, and TLS 1.3 over UDP with 0-RTT for repeat connections and eliminating head-of-line blocking","Using raw IP instead of UDP","Replacing DNS with a new protocol"],1,"QUIC combines connection setup and TLS 1.3, uses stream multiplexing to avoid HOL blocking, and achieves 0-RTT.","medium");

q(4,19,"After cwnd reaches ssthresh in TCP slow start, the algorithm switches to:",["Slow Start again","Congestion Avoidance – additive increase of cwnd by ~1 MSS per RTT","Fast Retransmit","Timeout-based retransmission only"],1,"Congestion Avoidance uses linear (additive) cwnd growth instead of exponential after reaching ssthresh.","hard");
q(4,19,"TCP head-of-line (HOL) blocking: a lost segment stalls all subsequent data in the byte stream. QUIC resolves this by:",["Using FEC at the physical layer","Implementing independent streams so a loss on one stream does not block delivery on others","Adding ordering to UDP","Blocking only at the application layer"],1,"QUIC's independent per-stream ordering means a packet loss in stream 1 does not delay data in stream 2.","hard");
q(4,19,"When a TCP sender receives three duplicate ACKs, it:",["Resets the connection","Immediately retransmits the missing segment (Fast Retransmit) without waiting for a timeout, then enters Fast Recovery","Doubles the retransmission timeout","Closes the connection"],1,"Three duplicate ACKs signal a likely loss; Fast Retransmit + Fast Recovery retransmit quickly without dropping cwnd to 1 MSS.","hard");
q(4,19,"The Nagle algorithm:",["Disables all small packet transmissions","Buffers small outgoing segments and coalesces them if there is outstanding unacknowledged data, reducing the number of small packets on the network","Forces immediate transmission of all segments","Increases cwnd aggressively"],1,"Nagle's algorithm: if unacknowledged data is in flight, buffer new small segments until ACK arrives or a full MSS accumulates.","hard");
q(4,19,"A TCP connection with RTT=100ms and a fixed receiver window of 64KB has a maximum throughput of approximately:",["100 Mbps","5.12 Mbps","64 Kbps","12.8 Mbps"],1,"Throughput = Window/RTT = (64*1024*8 bits) / 0.1 s = 5,242,880 bps ≈ 5.12 Mbps.","hard");

// topic 20 – Network Security  (7E 8M 5H)
q(4,20,"The CIA triad stands for:",["Cryptography, Integrity, Authentication","Confidentiality, Integrity, Availability","Certificate, Identity, Authorization","Cipher, Index, Algorithm"],1,"CIA: Confidentiality (only authorized access), Integrity (accurate and unaltered), Availability (accessible when needed).","easy");
q(4,20,"A firewall primarily:",["Encrypts all network traffic","Monitors and controls incoming/outgoing traffic based on predefined security rules","Assigns IP addresses","Provides VPN connectivity only"],1,"Firewalls enforce access control by inspecting packets and applying rules (source/destination IP, port, protocol, state).","easy");
q(4,20,"Which attack overwhelms a target with traffic to make it unavailable?",["Man-in-the-Middle (MITM)","SQL Injection","Denial of Service (DoS) / DDoS","Phishing"],2,"DoS/DDoS floods a target with requests/traffic, exhausting resources and causing unavailability.","easy");
q(4,20,"Symmetric encryption uses:",["Two different keys (public and private) for encryption and decryption","The same secret key for both encryption and decryption","Encryption only for data at rest","Encryption only of packet headers"],1,"Symmetric encryption: one shared key for both sides (e.g., AES, DES).","easy");
q(4,20,"A digital certificate binds:",["An IP address and a port number","A domain name and its web server IP address","A public key and its owner's identity, signed by a trusted Certificate Authority","A private key and a symmetric key"],2,"X.509 certificates bind a subject's identity to their public key, signed by a trusted CA to verify authenticity.","easy");
q(4,20,"Phishing is:",["A network scanning technique","A social engineering attack that tricks users into revealing credentials by impersonating trusted entities via fake emails or websites","A form of symmetric encryption","A denial-of-service technique"],1,"Phishing deceives users into disclosing credentials or installing malware via fraudulent communications.","easy");
q(4,20,"TLS provides which security services for web communications?",["Only authentication","Only confidentiality","Confidentiality, integrity, and authentication","Data compression only"],2,"TLS provides: confidentiality (encryption), data integrity (MAC/HMAC), and server/client authentication (certificates).","easy");

q(4,20,"A Man-in-the-Middle (MITM) attack is when:",["An attacker floods a server with requests","An attacker secretly intercepts and possibly modifies communications between two parties who believe they are communicating directly","An attacker exploits a SQL vulnerability","An attacker installs ransomware via email"],1,"MITM: the attacker positions themselves in the communication path, reading/altering traffic without the victims' knowledge.","medium");
q(4,20,"A salt in password hashing is used to:",["Encrypt the password symmetrically","Add a random value to each password before hashing, ensuring identical passwords produce different hashes and defeating rainbow table attacks","Compress the password for storage","Generate public/private key pairs"],1,"A cryptographic salt ensures that even identical passwords produce distinct hash values, neutralizing precomputed rainbow tables.","medium");
q(4,20,"An IDS differs from an IPS in that:",["IDS blocks attacks; IPS only detects them","IPS detects attacks; IDS blocks them","IDS detects and alerts on suspicious activity; IPS also takes automated inline action to block the attack","They are identical"],2,"IDS is passive (alerts only); IPS is inline and can actively block, drop, or reset connections.","medium");
q(4,20,"AES (Advanced Encryption Standard) is:",["A public-key algorithm supporting 1024/2048-bit keys","A symmetric block cipher supporting 128-, 192-, and 256-bit keys","A hash function with 256-bit output","A stream cipher with variable key length"],1,"AES is a symmetric block cipher (128-bit block size) with key lengths of 128, 192, or 256 bits. It replaced DES as the NIST standard.","medium");
q(4,20,"Defense in depth means:",["Using the strongest single firewall available","Relying solely on perimeter security","Implementing multiple overlapping layers of security controls so that if one fails, others still protect the system","Encrypting only at the application layer"],2,"Defense in depth (layered security): multiple independent controls at different layers so no single failure compromises security.","medium");
q(4,20,"PKI (Public Key Infrastructure) provides:",["Symmetric key distribution only","A framework for creating, managing, distributing, using, storing, and revoking digital certificates","A VPN tunneling protocol","A firewall rule management system"],1,"PKI manages digital certificates and public-key encryption, including CAs, RAs, and revocation mechanisms (CRL/OCSP).","medium");
q(4,20,"SQL injection is prevented primarily by:",["Firewalls alone","Parameterized queries (prepared statements) that separate SQL code from user data, plus input validation","Rate limiting","AES encryption of database files"],1,"Parameterized queries ensure user input is always treated as data, never as SQL syntax.","medium");
q(4,20,"VPNs create secure tunnels using which common protocols?",["A physical private network","IPSec and SSL/TLS-based VPNs (e.g., OpenVPN) that encrypt traffic over public networks","A cloud-based firewall solution","A DNS security extension"],1,"VPNs extend private networks over public networks using IPSec (site-to-site) or SSL/TLS-based tunnels (remote access).","medium");

q(4,20,"For Alice to send Bob a confidential message using asymmetric cryptography, she should encrypt with:",["Alice's private key","Bob's public key","A shared symmetric key","Alice's public key"],1,"Encrypt with the recipient's public key; only the recipient's private key can decrypt – ensuring confidentiality.","hard");
q(4,20,"A digital signature differs from a MAC in that:",["No difference – both use symmetric keys","A digital signature uses the sender's private key (providing non-repudiation verifiable by anyone with the public key); a MAC uses a shared symmetric key (authentication/integrity but no non-repudiation)","MACs use public-key cryptography; signatures use symmetric keys","A digital signature only ensures confidentiality"],1,"Signatures: asymmetric, non-repudiation. MACs: symmetric, only authentication/integrity – either party could have created a MAC.","hard");
q(4,20,"A Cross-Site Scripting (XSS) attack injects:",["Malicious SQL into a database query","Malicious scripts (JavaScript) into web pages served to other users, executing in their browsers to steal cookies or perform actions on their behalf","A DDoS flood targeting web servers","A MITM attack on HTTPS traffic"],1,"XSS injects client-side scripts into pages viewed by victims, enabling cookie theft, UI redress, and actions on behalf of the user.","hard");
q(4,20,"TLS 1.3 improved security over TLS 1.2 by removing:",["ECDHE key exchange","RSA key exchange (static RSA) and older cipher suites (RC4, 3DES, MD5, SHA-1 in handshakes), enforcing forward secrecy via ephemeral key exchange for all sessions","SHA-256 hashing","Certificate-based authentication"],1,"TLS 1.3 removed non-forward-secret key exchange (static RSA) and obsolete algorithms, mandating ECDHE/DHE for all cipher suites.","hard");
q(4,20,"A zero-day vulnerability is:",["A vulnerability discovered on the first day of product release","A security flaw unknown to or unaddressed by the vendor for which no patch exists, immediately exploitable upon discovery","A vulnerability requiring physical access","A theoretical vulnerability not yet exploitable"],1,"Zero-day: the vendor has had zero days to prepare a fix. Exploitation before a patch is a zero-day attack.","hard");

// ─────────────────────────────────────────────────────────────
// OOP  subject_id = 5
// ─────────────────────────────────────────────────────────────

// topic 21 – Inheritance  (7E 8M 5H)
q(5,21,"Inheritance in OOP allows a class to:",["Hide data inside objects","Derive properties and behaviors from another class","Create multiple objects from one class","Overload operators"],1,"Inheritance lets a subclass acquire attributes and methods of a superclass, enabling code reuse and IS-A relationships.","easy");
q(5,21,"In Java, which keyword makes a class inherit from another class?",["implements","inherits","extends","derives"],2,"class SubClass extends SuperClass establishes an inheritance relationship in Java.","easy");
q(5,21,"A subclass (derived class) is one that:",["Has no methods","Inherits attributes and behaviors from a parent class","Cannot be instantiated","Has only a private constructor"],1,"A subclass inherits all non-private members of its superclass and may add new features or override inherited ones.","easy");
q(5,21,"The 'super' keyword in Java is used to:",["Create a new instance of the superclass","Call the superclass constructor or invoke an overridden superclass method from within a subclass","Declare a superclass","Make a method final"],1,"super() calls the parent constructor; super.method() calls the parent's overridden version.","easy");
q(5,21,"Does Java support multiple inheritance of classes?",["Yes, using extends with multiple classes","No – multiple inheritance of classes is not allowed; multiple interface implementation is allowed","Yes, using the implements keyword","No, Java does not support any form of multiple inheritance"],1,"Java prevents multiple class inheritance to avoid the diamond problem but allows implementing multiple interfaces.","easy");
q(5,21,"Inheritance models which relationship?",["HAS-A","USES-A","IS-A","CREATES-A"],2,"Inheritance models IS-A: Dog IS-A Animal, so Dog can inherit from Animal.","easy");
q(5,21,"Applying the 'final' keyword to a class in Java prevents:",["Creating objects from the class","Inheriting from (subclassing) the class","Calling methods of the class","Accessing public fields"],1,"A final class cannot be extended. Example: java.lang.String is final.","easy");

q(5,21,"The diamond problem in multiple inheritance arises because:",["There is a problem with pointer arithmetic in C++","Ambiguity about which copy of a grandparent class's members to use when two parent classes share a common ancestor","Two methods have the same name","Memory is wasted due to virtual destructors"],1,"Diamond problem: D inherits from B and C which both inherit from A, creating two copies of A and method resolution ambiguity.","medium");
q(5,21,"Virtual inheritance in C++ ensures:",["All methods are polymorphic","Only one shared instance of a base class exists when diamond inheritance occurs","All methods are virtual","Base classes cannot be instantiated"],1,"C++ virtual inheritance: the diamond base class is shared (one instance) across the hierarchy instead of being duplicated.","medium");
q(5,21,"Method overriding requires that the subclass method have:",["A different method name","A different return type","The same method name, parameter list, and a compatible (same or covariant) return type as the parent method","The same name but different parameters"],2,"An overriding method must match the parent method's signature and have a compatible return type.","medium");
q(5,21,"The Liskov Substitution Principle (LSP) states:",["A class should have only one reason to change","Objects of a superclass should be replaceable by objects of a subclass without altering correctness","A class should depend on abstractions not concretions","Clients should not depend on interfaces they do not use"],1,"LSP: any code that uses a base-class reference must work correctly when a derived-class object is substituted.","medium");
q(5,21,"In Java, which members of a parent class are inherited by a subclass?",["Only public members","Only private members","All non-private members (public, protected, and package-private within the same package)","All members including private"],2,"Private members are not inherited; all other (non-private) members are accessible to subclasses.","medium");
q(5,21,"Constructor chaining in inheritance means:",["Calling multiple constructors of the same class in sequence","A subclass constructor calls its superclass constructor (via super()) before its own initialization code executes","Creating a chain of method calls","Linking multiple objects through constructors"],1,"Constructor chaining ensures superclass state is initialized before subclass state; the compiler inserts super() if omitted.","medium");
q(5,21,"To make a parent-class method overridable by subclasses but inaccessible from unrelated external classes, use:",["public","private","protected","package-private (default)"],2,"Protected allows subclass overriding across packages but hides the method from unrelated external classes.","medium");
q(5,21,"The fragile base class problem is that:",["Base class constructors are always fragile","Changes to a base class can unexpectedly break subclasses that depended on its implementation details","Base classes cannot have abstract methods","Derived classes cannot call super methods"],1,"Subclasses that rely on base-class implementation details can break silently when the base class is modified.","medium");

q(5,21,"The Java initialization order when constructing a subclass object is:",["Subclass static then superclass static then constructors top-down","Superclass static initializers, subclass static initializers, then superclass instance init + constructor, then subclass instance init + constructor","All constructors then all initializers","No specific order guaranteed"],1,"Java order: superclass statics, subclass statics, superclass instance init + ctor, subclass instance init + ctor.","hard");
q(5,21,"A a = new C(); a.foo(); where A, B, C each define foo() and C extends B extends A. Which foo() executes?",["A.foo()","B.foo()","C.foo()","Compile error"],2,"Dynamic dispatch: the runtime type of the object is C, so C.foo() is called regardless of the reference type A.","hard");
q(5,21,"Covariant return types in Java (since Java 5) allow:",["A subclass to override a method with a return type that is a supertype of the original","A subclass to override a method with a return type that is a subtype of the original return type","Return types to be changed freely","Covariant returns only for constructors"],1,"Java 5+: an overriding method may return a more specific (subtype) return type than the overridden method.","hard");
q(5,21,"Method hiding vs. method overriding in Java:",["They are identical","Overriding applies to instance methods (resolved by runtime dynamic dispatch); hiding applies to static methods (resolved at compile-time by reference type)","Hiding uses @Override; overriding does not","Hiding applies only to private methods"],1,"Instance methods are overridden (virtual dispatch); static methods are hidden (resolved by declared reference type).","hard");
q(5,21,"class A { void m() { h(); } void h() { print('A'); } } class B extends A { void h() { print('B'); } } A o = new B(); o.m(); prints:",["A","B","AB","Compile error"],1,"A.m() calls this.h(); the runtime type of 'o' is B, so dynamic dispatch invokes B.h(), printing B.","hard");

// topic 22 – Polymorphism  (7E 8M 5H)
q(5,22,"Polymorphism in OOP is the ability of:",["Having multiple constructors in one class","Different objects to respond differently to the same interface or method call","Hiding data within a class","Extending one class from another"],1,"Polymorphism: the same interface or method name invokes type-specific behavior depending on the actual object type.","easy");
q(5,22,"Method overloading achieves which type of polymorphism?",["Runtime polymorphism","Compile-time (static) polymorphism","Dynamic polymorphism","Interface polymorphism"],1,"Overloading is resolved at compile time by the method signature – it is compile-time (static) polymorphism.","easy");
q(5,22,"Method overriding achieves which type of polymorphism?",["Compile-time polymorphism","Runtime (dynamic) polymorphism","Operator polymorphism","Template polymorphism"],1,"Overriding is resolved at runtime using dynamic dispatch based on the actual object type.","easy");
q(5,22,"Method overloading is:",["Providing a new implementation of an inherited method in a subclass","Defining multiple methods with the same name but different parameter lists within the same class","Using a method across multiple classes","Calling a method from a different class"],1,"Overloaded methods share a name but differ in number or types of parameters; the compiler selects the right one.","easy");
q(5,22,"The @Override annotation in Java is used to:",["Create a new method in a subclass","Signal the compiler that the method intends to override a superclass method – a compile-time error is raised if the signature does not match","Mark a method as final","Indicate a method is static"],1,"@Override enables compile-time verification that an overriding relationship exists as intended.","easy");
q(5,22,"A virtual function in C++ is a member function declared with the 'virtual' keyword that:",["Has no body","Enables runtime polymorphic dispatch through a base-class pointer or reference via the vtable","Is static and shared across instances","Exists only in an interface"],1,"Virtual functions allow dynamic dispatch: the most-derived override is called at runtime through the vtable.","easy");
q(5,22,"Upcasting means:",["Converting a primitive to an object (boxing)","Assigning a subclass object reference to a superclass type reference","Calling a super method from a subclass","Converting from double to int"],1,"Upcasting is safe and implicit; it assigns a derived-class object to a base-class reference, enabling polymorphism.","easy");

q(5,22,"The vtable (virtual dispatch table) in C++ is:",["A table of all class member variables","A per-class table of function pointers to the most-derived virtual function implementations, used for O(1) runtime dispatch via a vptr in each object","A hash table for method lookup","A stack frame for function calls"],1,"Each class has a vtable; each object holds a vptr to its class's vtable enabling constant-time virtual dispatch.","medium");
q(5,22,"When a Java interface method is called on a reference whose actual runtime type is unknown at compile time, the call is resolved by:",["Static binding at compile time","Dynamic dispatch (virtual method table) at runtime","Direct function call","Macro substitution"],1,"Java interface calls are resolved at runtime using dynamic dispatch on the actual object's class.","medium");
q(5,22,"Parametric polymorphism (generics in Java / templates in C++) means:",["Polymorphism through method overriding","Writing type-independent code by parameterizing the type, resolved at compile time (C++) or type-erased at runtime (Java)","Polymorphism through interfaces only","Runtime-only polymorphism"],1,"Generics/templates enable type-safe, reusable algorithms and data structures for arbitrary types.","medium");
q(5,22,"Downcasting in Java requires:",["No cast – automatic like upcasting","An explicit cast and may throw ClassCastException at runtime if the object is not actually of the target type","Using the instanceof operator instead","The final keyword on the base class"],1,"Downcasting (base-to-derived) is explicit; the JVM throws ClassCastException if the actual type is wrong.","medium");
q(5,22,"Duck typing (common in Python) means:",["A form of polymorphism where explicit class hierarchy is required","Type compatibility determined by the presence of required methods/attributes rather than by explicit type hierarchy","A compile-time polymorphism technique","A way to cast types automatically"],1,"Duck typing: if an object has the required methods, it is treated as compatible regardless of its class hierarchy.","medium");
q(5,22,"An abstract class with all abstract methods differs from an interface in that:",["An abstract class cannot have constructors","An abstract class can have constructors, instance state, and concrete methods; it supports single inheritance. An interface is a pure contract supporting multiple type inheritance (with default/static methods since Java 8)","They are identical","Abstract classes are faster than interfaces"],1,"Abstract classes carry state and partial implementation; interfaces define contracts and support multiple-type inheritance.","medium");
q(5,22,"Ad-hoc polymorphism refers to:",["Generic programming with type parameters","Polymorphism defined for specific type combinations – examples include function overloading and operator overloading","Polymorphism through inheritance only","Runtime polymorphism via virtual functions"],1,"Ad-hoc: different behavior for each specific type combination (overloading, operator overloading) vs. universal parametric polymorphism.","medium");
q(5,22,"Object o = \"Hello\"; System.out.println(o.toString()); prints:",["Object@hashcode","Hello","Compile error","null"],1,"The actual runtime type is String. Dynamic dispatch calls String.toString() which returns the string value Hello.","medium");

q(5,22,"In C++, if a base class has a virtual destructor and a derived object is deleted through a base pointer:",["Only the base destructor runs (resource leak of derived members)","The derived destructor runs first then the base destructor, correctly releasing all resources","A segmentation fault occurs","The compiler refuses to compile this"],1,"Virtual destructor: delete through base pointer triggers vtable dispatch, calling the derived destructor first then the base.","hard");
q(5,22,"The time complexity of a virtual function call compared to a non-virtual call:",["O(n) versus O(1)","Both are O(1) – virtual adds a constant overhead (vptr dereference + indirect call) that inhibits inlining and branch prediction but is not asymptotically different","Virtual calls are O(log n)","No difference at all"],1,"Virtual dispatch is O(1) but adds constant overhead (pointer indirection) that can prevent inlining and flush branch predictors.","hard");
q(5,22,"Dynamic dispatch vs. static dispatch:",["Dynamic always compiles to the same machine code as static","Dynamic dispatch resolves the method at runtime by looking up the object's class hierarchy (MRO/vtable); static dispatch binds at compile time by declared type, enabling inlining but losing runtime flexibility","Dynamic is always slower by O(n)","No practical difference"],1,"Static dispatch enables inlining and optimization; dynamic dispatch enables runtime polymorphism at the cost of an indirect call.","hard");
q(5,22,"Java generics are invariant, meaning:",["List<Integer> is a subtype of List<Number>","List<Integer> is NOT a subtype of List<Number> even though Integer is a subtype of Number, preventing type-unsafe operations","Generics are always covariant","Generics are always contravariant"],1,"Invariance prevents adding a Double through a List<Number> reference that actually holds a List<Integer>.","hard");
q(5,22,"Covariance preserves subtyping direction while contravariance reverses it. In Java:",["No practical difference","Covariant: return types can be more specific in subtypes; Contravariant: parameter types can be more general in subtypes. Java generics use bounded wildcards (? extends / ? super) for co/contravariance","Covariance applies only to primitives","Contravariance is only for return types"],1,"? extends T gives read-only covariant access; ? super T gives write-only contravariant access – the PECS principle.","hard");

// topic 23 – Encapsulation  (7E 8M 5H)
q(5,23,"Encapsulation in OOP means:",["Allowing subclasses to access all parent class members","Bundling data (fields) and the methods that operate on them within a class, and restricting direct external access to internal state","Creating multiple instances of a class","Inheriting behavior from parent classes"],1,"Encapsulation combines data and behavior into a class unit and controls external access through access modifiers.","easy");
q(5,23,"Which access modifier restricts a field to the class where it is declared only?",["public","protected","package-private (default)","private"],3,"private: accessible only within the declaring class – not subclasses, same-package classes, or other packages.","easy");
q(5,23,"The purpose of getter (accessor) methods is to:",["Directly modify private fields","Provide controlled read access to private fields, optionally including validation or computation","Delete object instances","Override inherited methods"],1,"Getters expose private state in a controlled way, allowing the class to compute or validate values before returning them.","easy");
q(5,23,"The purpose of setter (mutator) methods is to:",["Read private field values","Provide controlled write access to private fields, optionally including input validation","Create new objects","Compare object values"],1,"Setters allow controlled modification with optional validation to enforce class invariants.","easy");
q(5,23,"A key benefit of encapsulation is:",["Making all fields globally accessible","Allowing internal implementation to change without affecting code that uses the class (loose coupling)","Preventing method overriding","Requiring more memory"],1,"Encapsulation hides implementation; external code using only the public API is unaffected when internals change.","easy");
q(5,23,"The 'public' access modifier means the member is:",["Accessible only within the class","Accessible only to subclasses and same package","Accessible from any class in any package","Accessible only within the same package"],2,"A public member has the widest access: any class in any package can use it.","easy");
q(5,23,"An immutable object is one that:",["Can be extended freely","Cannot have its state modified after construction – all fields are set in the constructor and there are no setters","Always has a private constructor","Has no fields"],1,"Immutable objects (e.g., Java's String, Integer) never change state after creation – inherently thread-safe.","easy");

q(5,23,"Data hiding (encapsulation) vs. abstraction:",["They are identical concepts","Data hiding hides internal implementation details from external users; abstraction provides a simplified interface hiding complexity – they complement each other","Abstraction is a subset of data hiding","Data hiding applies only to static members"],1,"Encapsulation hides HOW something is done; abstraction defines WHAT can be done – complementary OOP concepts.","medium");
q(5,23,"The JavaBean convention includes:",["Only public fields","Private fields with public getters/setters named getXxx()/setXxx() and a no-argument constructor, enabling automatic processing by frameworks and tools","A concurrency pattern for shared state","A singleton pattern"],1,"JavaBeans: private fields + getter/setter naming convention + no-arg constructor. Frameworks (Spring, Hibernate) rely on this for introspection.","medium");
q(5,23,"The principle of least privilege in class design means:",["Every class has full access to all other classes","Each component has access only to the minimum information and resources needed for its function – implemented through restrictive access modifiers","All fields should be public for maximum flexibility","All methods should be static"],1,"Least privilege: make fields private and methods no wider than necessary – reduces unintended coupling.","medium");
q(5,23,"Defensive copying in getters and setters solves:",["Prevention of method overriding","External code modifying mutable objects returned by or passed to a class, preserving the class's encapsulation invariants","Prevention of NullPointerExceptions","Method performance issues"],1,"Defensive copies prevent callers from mutating internal mutable objects (arrays, collections) obtained via getters.","medium");
q(5,23,"The 'protected' access modifier vs. package-private (default):",["No difference","Protected allows subclass access across packages AND same-package access; package-private is limited to the same package only","Package-private allows subclass access across packages; protected is same-package only","Protected is more restrictive than package-private"],0,"Protected is less restrictive: it grants access to subclasses anywhere plus same-package classes.","medium");
q(5,23,"The 'friend' keyword in C++:",["Is a class that inherits from another and strengthens encapsulation","Grants a specific class or function access to private/protected members, breaking encapsulation by bypassing access controls","Is a design pattern for proxy objects","Manages shared resources"],1,"C++ friend declarations bypass encapsulation; useful in tightly coupled cases (operator overloading) but increases coupling.","medium");
q(5,23,"Java records (Java 16+) provide:",["A mutable data container class","An immutable, transparent data-carrier class that auto-generates private final fields, public component accessor methods, equals(), hashCode(), and toString() – reducing encapsulation boilerplate","A database record mapping","A concurrency primitive"],1,"Java records declare immutable data classes compactly; the compiler generates all standard accessor and Object methods.","medium");
q(5,23,"Java access levels from most to least restrictive are:",["public > protected > package-private > private","private > package-private > protected > public","private > protected > package-private > public","package-private > private > protected > public"],1,"Restriction order: private (class only) < package-private (class+package) < protected (class+package+subclasses) < public (all).","medium");

q(5,23,"The Open/Closed Principle (OCP) as it relates to encapsulation means:",["Classes should be open for modification","Classes should be open for extension but closed for modification – new functionality is added by extending rather than changing existing code","Interfaces should always be open","Fields should always be public"],1,"OCP: well-encapsulated classes expose a stable interface and are extended (via inheritance or composition) without modifying existing code.","hard");
q(5,23,"Encapsulation supports thread safety in Java by:",["Making all methods synchronized by default","Ensuring state modifications occur through controlled methods that can be synchronized or use locks, preventing unsynchronized direct field access from concurrent threads","Encapsulation has no impact on thread safety","Making all fields volatile automatically"],1,"Centralizing state access in methods allows those methods to be synchronized or use concurrent utilities, controlling concurrent mutation.","hard");
q(5,23,"The internal vs. external interface problem in OOP encapsulation is:",["A problem with multiple inheritance","The tension between providing rich internal protected methods for subclasses and maintaining a clean public API – over-exposing protected internals creates a leaky API for subclasses as fragile as the public API","A networking problem","Exclusive to interfaces"],1,"Too many protected members create a 'protected API' that is just as costly to maintain as the public API, motivating composition over inheritance.","hard");
q(5,23,"Achieving true immutability in a class with mutable object references requires:",["Declaring the fields public final","Declaring the class final, all fields private final, defensive copying in constructors (copy incoming mutable objects) and in getters (return copies not references), and no setters","Using synchronized on all getters","Immutability is impossible with mutable fields"],1,"True immutability: final class + private final fields + no setters + defensive copy on constructor input and getter output.","hard");
q(5,23,"The Law of Demeter relates to encapsulation by:",["Being unrelated to encapsulation","Restricting method calls to the object itself, its fields, method parameters, and objects it creates – preventing call chains like a.getB().getC().doSomething() that expose internal object graph structure","Contradicting encapsulation","Applying only to data structures"],1,"LoD (don't talk to strangers) preserves encapsulation by preventing clients from depending on the internal structure of an object graph.","hard");

// topic 24 – Design Patterns  (7E 8M 5H)
q(5,24,"Design patterns in software engineering are:",["Reusable source code libraries","General, reusable solutions to commonly occurring software design problems in a given context","Hardware design blueprints","Database schema templates"],1,"Design patterns are proven templates for solving recurring design problems – not code, but adaptable blueprints.","easy");
q(5,24,"Which pattern ensures a class has only one instance and provides a global access point?",["Factory","Observer","Singleton","Decorator"],2,"Singleton restricts instantiation to one object, accessible globally through a static getInstance() method.","easy");
q(5,24,"Factory Method and Abstract Factory belong to which pattern category?",["Structural","Behavioral","Creational","Architectural"],2,"Creational patterns deal with object creation; Factory Method and Abstract Factory control instantiation without exposing creation logic.","easy");
q(5,24,"The Observer pattern defines a:",["One-to-one relationship","One-to-many dependency where the Subject notifies all Observers automatically when its state changes","Singleton relationship","Proxy relationship"],1,"Observer: Subject maintains a list of Observers and notifies them on state change – used in event systems and MVC.","easy");
q(5,24,"The Decorator pattern:",["Creates families of related objects","Dynamically adds responsibilities to objects by wrapping them in decorator objects that implement the same interface","Manages object lifecycle","Ensures single instances"],1,"Decorator attaches additional behavior at runtime by wrapping an object – more flexible than subclassing.","easy");
q(5,24,"Which pattern provides a simplified interface to a complex subsystem?",["Adapter","Bridge","Facade","Proxy"],2,"Facade provides a simple, unified interface to a set of complex subsystem interfaces.","easy");
q(5,24,"The Strategy pattern allows:",["Creating objects without specifying the exact class","A family of algorithms to be defined and made interchangeable at runtime without altering the client","Composing objects in tree structures","Notifying multiple observers of state changes"],1,"Strategy encapsulates interchangeable algorithms; the client can swap strategies at runtime.","easy");

q(5,24,"Factory Method vs. Abstract Factory:",["They are identical","Factory Method defines an interface for creating one product type, letting subclasses decide the concrete class; Abstract Factory provides an interface for creating families of related products without specifying concrete classes","Abstract Factory creates only one type of object","Factory Method uses static methods only"],1,"Factory Method: one product, subclass decides. Abstract Factory: creates related product families via grouped factory methods.","medium");
q(5,24,"Which GoF pattern decouples an abstraction from its implementation so both can vary independently?",["Adapter","Bridge","Decorator","Composite"],1,"Bridge separates abstraction from implementation using composition, allowing both to evolve independently.","medium");
q(5,24,"The Proxy pattern provides:",["Related families of objects","A substitute/placeholder for another object, controlling access and optionally adding lazy initialization, logging, or caching before delegating to the real object","Composing objects in tree structures","Making incompatible interfaces work together"],1,"Proxy types: Virtual (lazy init), Protection (access control), Remote (local representative), Caching.","medium");
q(5,24,"The Command pattern encapsulates:",["Object creation logic","A request as an object, enabling parameterization, queuing, logging, and undoable operations","Algorithms as interchangeable strategies","Object state for later restoration"],1,"Command: each operation becomes an object with execute() and optionally undo() – enables queuing, macros, and undo/redo.","medium");
q(5,24,"The Composite pattern is best used for:",["Manipulating single objects only","Part-whole hierarchies where individual (leaf) and composite objects are treated uniformly through a common interface","Creating platform-independent code","Managing object lifecycle"],1,"Composite: tree structures where clients treat leaves and composites the same (e.g., file system File and Directory).","medium");
q(5,24,"Adapter vs. Bridge:",["No difference","Adapter makes existing incompatible interfaces work together (structural, often retrofitted); Bridge proactively separates a new abstraction from its implementation from the start","Bridge retrofits interfaces; Adapter plans for variability","Adapter is behavioral; Bridge is creational"],1,"Adapter solves existing interface mismatch; Bridge is a forward-looking design decision for independent variation of abstraction and implementation.","medium");
q(5,24,"To save instantiation cost by sharing fine-grained objects with shared intrinsic state, use:",["Singleton","Prototype","Object Pool","Flyweight"],3,"Flyweight shares intrinsic (invariant) state among many fine-grained objects; extrinsic state is passed at use time.","medium");
q(5,24,"The Template Method pattern:",["Creates object templates","Defines the skeleton of an algorithm in a base-class method, deferring specific steps to subclasses that override them without changing the overall structure","Creates complex objects step by step","Composes objects in tree structures"],1,"Template Method: base class defines the algorithm skeleton; subclasses override specific steps (hooks).","medium");

q(5,24,"The key trade-off of Singleton in enterprise software is:",["It speeds up object creation","It introduces global mutable state, making code hard to test (cannot inject alternatives), creating tight coupling, and requiring careful thread-safe implementation (double-checked locking with volatile or enum-based Singleton)","It uses more memory than factory patterns","It prevents the use of interfaces"],1,"Singleton: global state, hidden dependencies, difficult mocking in unit tests, thread-safety concerns – significant trade-offs.","hard");
q(5,24,"To implement an undo/redo mechanism where each action is reversible, use:",["Strategy","Observer","Command with a history stack","Decorator"],2,"Command stores each action as an object with execute()/undo(); a history stack supports undo by popping and calling undo().","hard");
q(5,24,"MVC architecture typically embeds which design patterns?",["Only Singleton","Observer (Model notifies Views of state changes), Strategy (Controller behavior can vary), and Composite (Views composed of sub-views)","Only Factory","Only Decorator"],1,"MVC is built from GoF patterns: Observer (model→view notification), Strategy (controller), Composite (view hierarchy).","hard");
q(5,24,"Double-checked locking for Singleton was historically broken in Java because:",["It uses two locks instead of one","Pre-Java 5, the JMM allowed reordering that could expose a partially constructed object to other threads without the volatile keyword on the instance field","It is only relevant to C++","It creates multiple Singletons"],1,"Java 5+ with a volatile Singleton field fixes double-checked locking by establishing a happens-before relationship on object publication.","hard");
q(5,24,"Singleton vs. Flyweight:",["They are equivalent patterns","Singleton ensures ONE global instance of an entire class; Flyweight shares many fine-grained objects with common intrinsic state while unique extrinsic state is passed at use time – many Flyweight instances can exist","Flyweight creates new instances; Singleton shares them","Singleton is for performance; Flyweight for correctness"],1,"Singleton: one instance globally. Flyweight: many shared objects with shared intrinsic state (e.g., character glyph objects in a document editor).","hard");

// topic 25 – Exception Handling  (7E 8M 5H)
q(5,25,"An exception in Java is:",["A syntax error detected by the compiler","An event that disrupts normal program execution flow, typically caused by an error or unexpected condition at runtime","A design pattern for error handling","A deprecated method call"],1,"An exception is a runtime event representing an abnormal condition; Java's exception mechanism transfers control to appropriate handler code.","easy");
q(5,25,"Checked vs. unchecked exceptions in Java:",["Checked exceptions are faster","Checked exceptions must be declared in the method signature or caught (enforced by the compiler); unchecked exceptions (RuntimeException subclasses) do not require declaration or catching","Unchecked exceptions are caught at compile time","There is no difference"],1,"Checked: compiler-enforced handling. Unchecked (RuntimeException/Error): no forced handling – typically programming errors or JVM failures.","easy");
q(5,25,"The 'finally' block in Java:",["Executes only when no exception is thrown","Executes only when an exception is thrown","Always executes whether or not an exception is thrown or caught","Catches exceptions missed by other catch blocks"],2,"Finally always runs – used for cleanup; try-with-resources is preferred since Java 7.","easy");
q(5,25,"The root of all Java exceptions and errors is:",["Exception","RuntimeException","Throwable","Error"],2,"Throwable is the superclass of both Exception (recoverable) and Error (serious JVM failures).","easy");
q(5,25,"The 'throws' keyword in a method signature is used to:",["Actually throw an exception at that point","Declare that the method may throw one or more checked exceptions, requiring callers to handle or propagate them","Catch exceptions within the method","Import exception classes"],1,"throws advertises which checked exceptions a method may propagate to its callers.","easy");
q(5,25,"The 'throw' keyword is used to:",["Declare which exceptions a method might throw","Explicitly create and throw an exception object at a specific point in code","Catch exceptions","Import exception handling libraries"],1,"throw new SomeException(...) transfers control to the nearest matching catch block.","easy");
q(5,25,"Which Java 7+ construct automatically closes resources implementing AutoCloseable?",["finally block","catch block","try-with-resources","throws declaration"],2,"try-with-resources: resources declared in try() are automatically closed after the block, even if an exception occurs.","easy");

q(5,25,"Exception propagation in Java means:",["Converting one exception type to another","If a method does not catch an exception, it propagates up the call stack until caught or the program terminates with an unhandled exception","Logging all exceptions automatically","Catching all exceptions in a single handler"],1,"Uncaught exceptions bubble up through the call stack until a matching handler is found or the JVM terminates.","medium");
q(5,25,"Exception chaining (wrapping) involves:",["Catching multiple exception types in one catch block","Catching a lower-level exception and re-throwing it as a higher-level exception (with the original as the cause), preserving the root stack trace while exposing a meaningful abstraction to the caller","Declaring multiple throws clauses","Using multiple catch blocks for one try"],1,"throw new ServiceException('msg', originalEx) wraps low-level details; getCause() preserves the root cause for debugging.","medium");
q(5,25,"Multi-catch (Java 7+) allows:",["Catching all exceptions with a single Throwable","A single catch block to handle multiple exception types: catch(IOException | SQLException e) – reducing duplicated handling code","Rethrowing exceptions automatically","Catching exceptions in parallel"],1,"Multi-catch: one catch block for multiple exception types that would otherwise need identical handling code.","medium");
q(5,25,"When both a catch block and a finally block throw exceptions:",["Both exceptions are propagated together","The finally exception silently replaces the catch exception, hiding the original","The catch exception takes priority","A CompositeException is created"],1,"A finally-thrown exception discards any pending catch exception. try-with-resources uses addSuppressed() to preserve both.","medium");
q(5,25,"The Null Object Pattern's relationship to exception handling is that it:",["Replaces try-catch blocks entirely","Provides a default do-nothing object instead of returning null, eliminating NullPointerExceptions caused by callers forgetting null checks","Catches NullPointerExceptions automatically","Applies only to checked exceptions"],1,"Null Object returns a safe no-op default, proactively avoiding NPEs without requiring defensive null checks everywhere.","medium");
q(5,25,"The Error class in Java represents:",["User-defined application errors","Serious JVM-level failures (OutOfMemoryError, StackOverflowError) that are generally unrecoverable – most programs should not catch Error","All RuntimeExceptions","Checked exceptions that require declaration"],1,"Errors indicate catastrophic JVM conditions; catching them is almost never meaningful and may leave the JVM in an undefined state.","medium");
q(5,25,"Poorly designed exception hierarchies violate OCP when:",["Exceptions cannot be extended","Callers must use instanceof to check specific exception types, requiring code modification every time a new exception type is added","Checked exceptions violate OCP by definition","Exceptions should be open for catching"],1,"Good hierarchies: catch ServiceException handles all subtypes. Flat hierarchies: every new subtype forces callers to add new catch blocks.","medium");
q(5,25,"Exception swallowing (catch(Exception e) {}) is bad practice because:",["It logs the exception with full detail – good practice","It silently hides errors, making downstream failures extremely difficult to diagnose","It re-throws with additional context","It declares many exception types"],1,"An empty catch block consumes exceptions silently; code appears to work but errors are hidden, causing mysterious later failures.","medium");

q(5,25,"An overriding method in Java can declare it throws:",["Any additional checked exceptions beyond those the parent declares","No new or broader checked exceptions than the overridden method (only fewer, narrower, or unchecked exceptions) to maintain the Liskov Substitution Principle","Any additional exception types if the subclass adds a new throws clause","Any exceptions if the parent declares no exceptions"],1,"LSP: callers using the parent type must not be surprised by exceptions not declared in the parent's contract.","hard");
q(5,25,"How does try-with-resources handle suppressed exceptions when both the try body and close() throw?",["The close() exception is prioritized; the try-body exception is lost","The try-body exception is the primary; the close() exception is added as a suppressed exception via addSuppressed(), both accessible to the caller","Both are merged into one","A RuntimeException wraps both"],1,"try-with-resources: E1 (try body) is primary; E2 (close) is suppressed via addSuppressed() – no diagnostic information is lost.","hard");
q(5,25,"The 'fail-fast' principle in error handling means:",["Systems retry silently until success","Detecting and reporting errors as early as possible at the point of invalid input (precondition checking with IllegalArgumentException/requireNonNull) rather than propagating invalid state deep into the system","Catching all exceptions globally at startup","Delaying exception handling to the UI layer"],1,"Fail-fast: validate inputs at entry points and throw immediately – errors are caught near their source with clear context.","hard");
q(5,25,"Best practice for exception translation between architecture layers (Controller > Service > Repository) is to:",["Propagate all SQL/IO exceptions unchanged to the controller","Catch low-level technical exceptions in each layer and rethrow domain-specific exceptions meaningful at the higher layer, using chaining to preserve the root cause","Swallow all exceptions in the service layer","Declare all exceptions as checked at every boundary"],1,"Layer isolation: catch technical exceptions (SQLException) in the Repository, rethrow domain exceptions (DataAccessException) for the Service layer – each layer speaks its own exception language.","hard");
q(5,25,"A try-catch-rethrow pattern is appropriate when:",["Catching an exception and ignoring it","Catching an exception to perform partial cleanup or logging specific to this scope, then rethrowing (as-is or wrapped) so the caller still receives the error signal","Catching all Exception types in one block","Catching exceptions only in main()"],1,"Rethrow after local responsibility: log or clean up what this scope owns, then propagate the exception (possibly wrapped) upward.","hard");

// ─────────────────────────────────────────────────────────────
