// topic 26 – SDLC  (7E 8M 5H)
q(6,26,"SDLC stands for:",["Software Design and Lifecycle Components","System Development and Logic Concepts","Software Development Life Cycle","System Design Lifecycle Criteria"],2,"SDLC is a structured process defining phases for planning, creating, testing, and maintaining software.","easy");
q(6,26,"User requirements are gathered and documented in which SDLC phase?",["Design","Implementation","Requirements Analysis","Testing"],2,"Requirements Analysis identifies and documents stakeholder needs through interviews, surveys, and workshops.","easy");
q(6,26,"The Waterfall model is characterized by:",["Iterative development cycles with frequent releases","Sequential linear phases where each phase completes before the next begins with limited backward movement","Continuous integration and deployment","No formal documentation requirements"],1,"Waterfall flows linearly: Requirements→Design→Implementation→Testing→Maintenance. Rigid; best for stable, well-understood requirements.","easy");
q(6,26,"In SDLC, which phase converts the design into actual source code?",["Requirements","Design","Implementation (Coding)","Maintenance"],2,"The Implementation phase translates design blueprints into working software using programming languages and tools.","easy");
q(6,26,"The primary purpose of the System Design phase is to:",["Gather user requirements","Translate requirements into a system blueprint defining architecture, data structures, interfaces, and components","Write and test code","Deploy the system to users"],1,"System Design converts requirements into a detailed technical design: architecture, data models, interface designs, and component specifications.","easy");
q(6,26,"Which SDLC phase handles bug fixes, updates, and improvements after deployment?",["Analysis","Design","Implementation","Maintenance"],3,"Maintenance covers corrective (bug fixes), adaptive (environment changes), perfective (enhancements), and preventive (refactoring) work.","easy");
q(6,26,"Feasibility analysis in SDLC determines:",["The exact system requirements","Whether the proposed project is technically possible, economically viable, legally permissible, and operationally feasible","The detailed system design","The testing strategy"],1,"Feasibility study covers: Technical, Economic, Legal, Operational, and Schedule feasibility.","easy");

q(6,26,"The Spiral model's main advantage over Waterfall is:",["It eliminates all documentation","It incorporates iterative risk management, addressing the riskiest elements first in each spiral before committing to full development","It is simpler to implement","It requires no stakeholder involvement"],1,"Spiral model: each loop includes risk analysis, prototyping, and evaluation – high-risk elements tackled early.","medium");
q(6,26,"The V-Model in software development:",["Is a version control methodology","Pairs each development phase with a corresponding testing phase designed in parallel (Requirements↔Acceptance Testing, System Design↔System Testing, etc.)","Uses version numbers for all artifacts","Is a visual modeling language"],1,"V-Model emphasizes test planning alongside development; each phase has a corresponding validation phase.","medium");
q(6,26,"A Software Requirements Specification (SRS) is:",["Source code documentation","A formal document completely describing the behavior of the system to be developed, serving as a contract between the development team and stakeholders","A test plan document","A project management schedule"],1,"SRS captures functional and non-functional requirements, constraints, interfaces, and performance requirements.","medium");
q(6,26,"Functional requirements differ from non-functional requirements in that:",["Functional requirements describe performance; non-functional describe features","Functional requirements describe WHAT the system must do (specific behaviors); non-functional describe HOW WELL it must perform (quality attributes: performance, security, scalability)","They are identical","Non-functional requirements are optional"],1,"Functional: system behaviors. Non-functional: quality attributes (performance, availability, security).","medium");
q(6,26,"The purpose of prototyping in SDLC is to:",["Replace the final system","Create an early partial version to validate requirements, demonstrate feasibility, and gather user feedback before committing to full development","Document the database schema","Replace testing phases"],1,"Prototyping validates assumptions and discovers requirement gaps early, before expensive full development.","medium");
q(6,26,"Requirements traceability enables:",["Tracking the team's daily activities","Tracing each requirement to its source, design elements, code, and test cases – ensuring complete coverage and enabling impact analysis when requirements change","Versioning requirements documents","Monitoring production system performance"],1,"RTM (Requirements Traceability Matrix) links requirements to tests and code, ensuring nothing is missed and changes are managed.","medium");
q(6,26,"The Incremental SDLC model delivers software:",["All at once in a single release","In a series of builds (increments) each adding functionality to a working system, allowing early delivery of partial value","Without formal requirements","Via separate parallel teams with no integration"],1,"Incremental: each release adds features to a working system; stakeholders get value earlier than with a full-release model.","medium");
q(6,26,"Configuration Management in SDLC is:",["Managing hardware configurations","A discipline for systematically identifying, controlling, and tracking software artifacts and their changes throughout the project lifecycle","Managing network configurations","A project scheduling technique"],1,"SCM covers version control, change control, configuration status accounting, and configuration auditing.","medium");

q(6,26,"McCabe's Cyclomatic Complexity measures:",["Lines of code in a module","The number of linearly independent paths through source code, computed as E - N + 2P (edges minus nodes plus 2 * connected components)","The number of bugs per function","Test coverage percentage"],1,"Cyclomatic Complexity = E-N+2P or decision points+1. CC > 10 is often considered too complex for safe testing.","hard");
q(6,26,"The Software Crisis of the late 1960s-70s led to:",["A shortage of software developers","Recognition that software projects consistently ran over budget and schedule with poor quality, motivating the emergence of Software Engineering as a discipline with structured methodologies and rigorous project management","A hardware compatibility crisis","A security crisis"],1,"The Software Crisis motivated NATO Software Engineering conferences (1968-69) and establishment of SE as a formal discipline.","hard");
q(6,26,"Verification vs. Validation in software QA:",["They are the same","Verification: are we building the product right? (conformance to specs, internal consistency). Validation: are we building the right product? (does it meet user needs?)","Verification is testing; Validation is code review","Validation happens before verification"],0,"Verification=conformance to specification; Validation=fitness for user purpose. Both are essential SQA activities.","hard");
q(6,26,"Function Point Analysis (FPA) is:",["Counting the number of functions in a program","A language-independent sizing technique measuring software size based on user-perceived functionality (inputs, outputs, inquiries, internal files, external interfaces) to estimate effort, cost, and schedule","A testing metric for function coverage","A design pattern for functional decomposition"],1,"FPA quantifies software in functional units independent of implementation technology, enabling technology-agnostic estimation.","hard");
q(6,26,"The COCOMO model estimates software cost using:",["A network design formula","An algorithmic formula: Effort = a*(Size)^b * EAF, where EAF incorporates cost drivers (product, platform, personnel, project factors)","A database design methodology","A test coverage model"],1,"COCOMO (and COCOMO II): effort estimated from size (KLOC or FP) adjusted by cost drivers including team capability, tool support, and required reliability.","hard");

// topic 27 – Agile & Scrum  (7E 8M 5H)
q(6,27,"The four core values of the Agile Manifesto are:",["Process, Tools, Documentation, Contracts","Individuals and interactions, Working software, Customer collaboration, Responding to change – valued more than their counterparts (processes/tools, documentation, contracts, plans)","Planning, Design, Code, Test","Waterfall, Spiral, Agile, Lean"],1,"Agile Manifesto (2001): while right-side items have value, the left-side items are valued more.","easy");
q(6,27,"A Sprint in Scrum is:",["A meeting to review the product","A time-boxed iteration (typically 1-4 weeks) during which a Scrum team creates a potentially shippable product increment","A document listing all product requirements","A role in the Scrum team"],1,"A Sprint is a fixed time-box (commonly 2 weeks) for planning, developing, and testing a potentially releasable increment.","easy");
q(6,27,"In Scrum, the Product Backlog is managed and prioritized by the:",["Scrum Master","Development Team","Product Owner","Stakeholder"],2,"The Product Owner maximizes product value by owning and ordering the Product Backlog based on business priorities.","easy");
q(6,27,"The Scrum Master's primary role is to:",["Write user stories","Assign tasks to developers","Facilitate Scrum events, remove impediments, and coach the team on Scrum principles","Manage the project budget"],2,"Scrum Master: servant-leader who ensures Scrum is practiced correctly, removes blockers, and shields the team.","easy");
q(6,27,"The Product Backlog in Scrum is:",["The list of completed features","An ordered list of all desired product work (stories, features, bugs, technical tasks) maintained and prioritized by the Product Owner","The plan for a single Sprint","A document listing team roles"],1,"The Product Backlog is dynamic; the Product Owner keeps highest-value items at the top for the team to pull into Sprints.","easy");
q(6,27,"The Daily Scrum is:",["A 1-hour detailed project status meeting","A 15-minute daily event for the Development Team to synchronize activities, inspect Sprint progress, and identify impediments","A weekly planning session","A product review with stakeholders"],1,"Daily Scrum: 15-minute time-boxed standup; developers plan the next 24 hours and surface blockers.","easy");
q(6,27,"The Sprint Retrospective's purpose is to:",["Demonstrate the product increment to stakeholders","Plan the next Sprint","Inspect how the last Sprint went regarding process, tools, and relationships, and create an improvement plan","Refine the Product Backlog"],2,"The Sprint Retrospective examines team working practices and produces concrete improvement actions for the next Sprint.","easy");

q(6,27,"The Definition of Done (DoD) in Scrum is:",["A list of user stories to complete in a Sprint","A shared understanding of what criteria every PBI must satisfy to be considered complete (e.g., coded, reviewed, tested, documented, integrated)","Acceptance criteria for one specific story","The Sprint Goal statement"],1,"DoD is a quality standard applied to every increment; it creates shared understanding of 'done' and ensures consistent quality.","medium");
q(6,27,"Velocity in Agile/Scrum is:",["The typing speed of individual developers","The average amount of work (story points) a team completes per Sprint, used for release planning and capacity estimation","The number of bugs fixed per Sprint","Deployment frequency"],1,"Velocity tracks team throughput per Sprint; averaged over multiple Sprints it forecasts future delivery rate.","medium");
q(6,27,"Kanban differs from Scrum in that:",["Kanban uses Sprints; Scrum does not","Kanban has fixed Sprints and defined roles; Scrum does not","Kanban limits Work In Progress (WIP) and has no fixed iterations or mandatory roles; Scrum uses time-boxed Sprints and prescribed roles (PO, SM, Dev Team)","They are identical"],2,"Kanban: continuous flow, WIP limits, no fixed cadence. Scrum: time-boxed Sprints, ceremonies, defined roles.","medium");
q(6,27,"Story Points in Agile are:",["A precise measure of hours","A relative abstract measure of effort and complexity (combining uncertainty, risk, and work) used for planning without committing to specific hours","A count of lines of code","A measure of velocity in hours per day"],1,"Story points are relative (an 8-point story is roughly twice as complex as a 4-pointer) and avoid false precision of hour estimates.","medium");
q(6,27,"A User Story follows which format?",["A detailed technical specification","As a [role], I want [feature], so that [benefit] – a short description of a feature from the user's perspective","A bug report","A database schema description"],1,"User stories articulate: who wants it, what they want, and why – focusing on user value rather than technical implementation.","medium");
q(6,27,"The Sprint Review's purpose is to:",["An internal team retrospective","Demonstrate the completed Sprint increment to stakeholders, gather feedback, and adapt the Product Backlog based on learnings","Plan the next Sprint","Daily status reporting"],1,"Sprint Review: informal demo to stakeholders; feedback drives Product Backlog adaptation.","medium");
q(6,27,"The first Agile Principle is:",["Plan the entire project upfront","Our highest priority is to satisfy the customer through early and continuous delivery of valuable software","Complete all documentation before coding","Follow a strict phase-gate process"],1,"Agile Principle #1: customer satisfaction through early and continuous delivery of valuable software is the highest priority.","medium");
q(6,27,"Continuous Integration (CI) in Agile means:",["Merging all code only at project end","Frequently merging code changes to a shared repository followed by automated build and test runs, detecting integration problems early","Running tests only on weekends","A documentation practice"],1,"CI: integrate at least daily; automated build and tests run immediately, catching conflicts and bugs when cheapest to fix.","medium");

q(6,27,"Technical debt in Agile is:",["Money owed for software licenses","The implied cost of rework caused by choosing quick/easy solutions now instead of better approaches; managed by allocating backlog items for refactoring and maintaining Definition of Done standards","Unused lines of code","The cost of hiring additional developers"],1,"Technical debt accrues 'interest': shortcuts taken now make future changes slower and riskier. Managed proactively with refactoring stories.","hard");
q(6,27,"Sprint Planning vs. Product Backlog Refinement:",["They are the same meeting","Sprint Planning is a time-boxed event where the team selects Sprint Backlog items and plans delivery; Backlog Refinement is an ongoing activity where PBIs are elaborated, estimated, and ordered before being needed for Sprint Planning","Backlog Refinement happens only once per project","Sprint Planning requires only the Product Owner"],1,"Refinement (grooming) is continuous pre-work; Sprint Planning creates the Sprint Goal and Sprint Backlog from ready PBIs.","hard");
q(6,27,"Scrum of Scrums is:",["A ceremony for very small Scrum teams","A scaling technique where representatives from multiple Scrum teams meet regularly to coordinate cross-team dependencies and resolve inter-team impediments","A retrospective format","A type of Planning Poker"],1,"Scrum of Scrums: scaling mechanism where team representatives (often Scrum Masters) sync to manage cross-team coordination.","hard");
q(6,27,"In SAFe, a Program Increment (PI) is:",["A single Sprint","A time-boxed period (typically 8-12 weeks / 4-5 Sprints) during which an Agile Release Train delivers incremental value against a program backlog, aligned via PI Planning","A single product release cycle","A single feature implementation"],1,"SAFe PI: a fixed cadence aligning multiple Agile teams (ART) around shared goals via a 2-day PI Planning event.","hard");
q(6,27,"The Agile principle of sustainable pace means:",["Teams should work as fast as possible","Teams work at a pace they can maintain indefinitely – avoiding burnout through overtime – because sustainable pace produces higher quality, better motivation, and more predictable delivery","Sustainable pace always means slower delivery","It conflicts with nothing in traditional PM"],1,"Sustainable pace prevents 'death march' projects; consistent output is more predictable and maintains code quality better than crunch cycles.","hard");

// topic 28 – Software Testing  (7E 8M 5H)
q(6,28,"Verification vs. Validation in software testing:",["They mean the same thing","Verification checks that we are building the product right (conformance to specs); Validation checks that we built the right product (meets user needs)","Verification tests code; Validation tests the database","Validation happens before verification"],1,"Verification = internal consistency with specifications. Validation = fitness for user purpose.","easy");
q(6,28,"Black-box testing focuses on:",["Testing with complete knowledge of internal code","Testing input/output behavior of the system without knowledge of internal implementation – test cases derived from specifications","Testing only the database layer","Testing hardware components"],1,"Black-box testing treats the system as opaque; only inputs, outputs, and specifications matter.","easy");
q(6,28,"White-box (structural) testing is based on:",["Testing only the user interface","Knowledge of internal code structure, designing tests to exercise specific paths, branches, and conditions","Testing only black-box functions","No specific knowledge"],1,"White-box testing uses code visibility to design tests for statement coverage, branch coverage, and path coverage.","easy");
q(6,28,"Unit testing verifies:",["The entire system as a whole","Individual components (functions, classes, modules) in isolation","Integration of multiple components","Behavior with real end-users"],1,"Unit tests exercise the smallest testable code units in isolation, using mocks to replace dependencies.","easy");
q(6,28,"Regression testing is:",["Testing a system for the first time","Re-testing previously working functionality after code changes to ensure new changes have not broken existing features","Performance testing under load","Testing only new features"],1,"Regression testing guards against unintended side effects of modifications on previously working functionality.","easy");
q(6,28,"A test case specifies:",["A type of programming error","Preconditions, inputs, execution steps, expected outputs, and postconditions – providing a repeatable procedure to verify a specific system behavior","The code being tested","A bug report"],1,"A test case is a documented, repeatable procedure for verifying one aspect of system behavior.","easy");
q(6,28,"Integration testing verifies that:",["Individual functions work in isolation","Multiple components work correctly when combined – testing interfaces and interactions between them","The entire system meets user requirements","Non-functional requirements are met"],1,"Integration tests check that independently developed components work together correctly at their interfaces.","easy");

q(6,28,"Code coverage measures:",["The percentage of requirements tested","How much of the source code is exercised by tests. Common types: statement, branch, path, and condition coverage","The number of test cases written","The percentage of bugs found"],1,"Coverage metrics reveal untested code; branch coverage is stronger than statement coverage. 100% coverage does not guarantee correctness.","medium");
q(6,28,"Equivalence partitioning divides the input domain into:",["Every possible input value","Partitions where the system should behave identically, then tests one representative per partition – reducing the number of needed tests","Edge cases only","Invalid inputs only"],1,"Equivalence partitioning: if one value in a partition passes, all values in that partition should behave the same.","medium");
q(6,28,"Boundary Value Analysis (BVA) focuses tests at:",["Random inputs","Partition boundaries (min, min+1, max-1, max) where errors are most likely to occur","Only invalid inputs","Only normal inputs"],1,"BVA complements equivalence partitioning; off-by-one errors and boundary conditions are common defect locations.","medium");
q(6,28,"Mocking in unit testing is used to:",["Create production implementations","Replace real dependencies (databases, external APIs) with controlled test doubles, enabling true unit isolation","Test the real system end-to-end","Measure code performance"],1,"Mocks replace external dependencies with controllable substitutes, making tests fast, deterministic, and isolated.","medium");
q(6,28,"System Testing validates:",["Individual components","The complete, integrated system against specified requirements in an environment resembling production","Code during development","Only unit-level behavior"],1,"System testing evaluates the fully integrated software against all system requirements.","medium");
q(6,28,"User Acceptance Testing (UAT) is performed by:",["Developers","End users or business stakeholders to verify the system meets business needs before production deployment","QA engineers using automated tools","CI/CD pipelines"],1,"UAT is the final gate where real users validate the system meets their actual business needs before go-live.","medium");
q(6,28,"Alpha testing vs. Beta testing:",["No difference","Alpha is in-house testing at the developer's site; Beta is conducted by external users in their own real-world environments","Alpha is automated; Beta is manual","Beta happens before Alpha"],0,"Alpha: internal QA/developers simulate real usage. Beta: limited external users test in real environments before release.","medium");
q(6,28,"Performance testing subtypes include:",["Only load testing","Load (normal workload), Stress (beyond normal limits), Spike (sudden surges), Volume (large data), and Soak (extended duration) testing","Security testing only","Database testing only"],1,"Performance testing validates non-functional quality attributes under various load scenarios.","medium");

q(6,28,"Mutation testing evaluates test suite quality by:",["Testing by modifying requirements","Introducing small deliberate code changes (mutants) and measuring what percentage of mutants are detected (killed) by existing tests – the mutation score","A form of exploratory testing","Testing database mutations"],1,"Mutation score = killed mutants / total mutants. A strong test suite kills most mutants; undetected mutants reveal test gaps.","hard");
q(6,28,"Property-based testing differs from example-based testing in that:",["No practical difference","Property-based testing verifies general invariants that must hold for ALL valid inputs by generating many random test cases automatically; example-based uses specific hand-crafted examples","Property-based testing only works for functional code","Property-based testing requires formal verification"],1,"Property-based (QuickCheck, Hypothesis): randomly generates thousands of inputs to verify a property always holds – finds edge cases humans miss.","hard");
q(6,28,"The Test Pyramid recommends:",["Maximizing E2E tests","A large base of fast unit tests, a middle layer of integration tests, and a small apex of slow E2E/UI tests – balancing speed, cost, and coverage","An equal number of each test type","Only unit tests"],1,"Test Pyramid (Mike Cohn): many fast cheap unit tests, fewer integration tests, very few slow expensive E2E tests. Inversion creates a slow fragile test suite.","hard");
q(6,28,"Test-Driven Development (TDD) uses the Red-Green-Refactor cycle, which means:",["Write tests after all code is complete","Red: write a failing test for the next small behavior; Green: write minimal code to pass; Refactor: improve code without breaking tests – short cycles drive design through tests","Only automated testing","Running tests continuously in CI/CD"],1,"TDD micro-cycle: failing test first drives emergent design, minimal passing code, then clean refactoring – with high unit test coverage as a byproduct.","hard");
q(6,28,"In software testing terminology, Error, Fault, and Failure are:",["All synonyms for bugs","Error: a human mistake; Fault/Defect: a static code anomaly resulting from the error; Failure: the observable incorrect behavior when a fault executes","Fault is worst; failure is minor","Failures occur at compile time; errors at runtime"],1,"IEEE standard: Error (human) → Fault/Defect (code) → Failure (observable). Not all faults cause failures (latent faults).","hard");

// topic 29 – Software Architecture  (7E 8M 5H)
q(6,29,"Software architecture is:",["The physical hardware structure of a system","The high-level structure of a software system defining its components, their relationships, and the principles governing design and evolution","The detailed code design of individual functions","The project management structure"],1,"Software architecture is the fundamental set of principal design decisions about system organization, components, connectors, and constraints.","easy");
q(6,29,"The Layered (N-Tier) architecture pattern organizes components into:",["One monolithic deployment","Horizontal layers (e.g., Presentation, Business Logic, Data Access) where each layer serves the one above and depends only on the one below","Many independent microservices","All components communicating directly with each other"],1,"Layered architecture separates concerns; each layer has defined responsibilities and communicates only with adjacent layers.","easy");
q(6,29,"Microservices architecture is an architectural style where:",["The application is one small monolith","The application is structured as a collection of small, independently deployable services each responsible for a specific business capability, communicating via APIs","The architecture is used only for embedded systems","A single database serves multiple applications"],1,"Microservices: small, autonomous services with their own process and data store, deployed independently.","easy");
q(6,29,"A Load Balancer in software architecture is used to:",["Store and retrieve data","Distribute incoming traffic across multiple server instances to improve performance, reliability, and scalability","Encrypt communications","Manage database connections"],1,"Load balancers prevent single-server bottlenecks, enable horizontal scaling, and improve availability through redundancy.","easy");
q(6,29,"The MVC (Model-View-Controller) architectural pattern separates concerns into:",["A database design pattern","Model (data and business logic), View (UI presentation), Controller (input handling and coordination between Model and View)","A network protocol pattern","A testing pattern"],1,"MVC: Model manages data/logic, View displays data, Controller handles user input and updates Model/View.","easy");
q(6,29,"Scalability in software architecture means:",["The ability to fix bugs quickly","The ability to handle increasing load by adding resources (horizontal: more machines) or upgrading resources (vertical: bigger machines) without redesigning the core system","The ability to add new features","Security hardening capability"],1,"Scalability: design for growth. Horizontal scaling adds nodes; vertical scaling adds power to existing nodes.","easy");
q(6,29,"An API Gateway in microservices architecture is:",["A database gateway","A single entry point for clients that routes requests to appropriate microservices and provides cross-cutting concerns like authentication, rate limiting, and response aggregation","A service registry for microservices","A message broker for async communication"],1,"API Gateway: front door for clients – handles routing, auth, SSL, rate limiting, and request transformation.","easy");

q(6,29,"The key trade-off between Monolithic and Microservices architectures is:",["Monolithic is always better for large systems","Monolithic is simpler to develop and test initially but harder to scale and maintain as it grows; Microservices provide independent scaling and deployment but introduce distributed system complexity (network failures, consistency, operational overhead)","Microservices are always better","There are no trade-offs"],1,"Monolith vs. Microservices: agility and scalability vs. operational complexity (service discovery, distributed tracing, eventual consistency).","medium");
q(6,29,"The SOLID principles are:",["A set of database design rules","Five OO design principles: Single Responsibility, Open/Closed, Liskov Substitution, Interface Segregation, and Dependency Inversion – guidelines for maintainable and extensible systems","A network security framework","A set of Agile practices"],1,"SOLID: SRP, OCP, LSP, ISP, DIP – foundational principles for flexible OO design.","medium");
q(6,29,"Event-Driven Architecture (EDA) is:",["A pattern where components communicate synchronously","An architectural pattern where components communicate through events – producers emit events without knowing consumers, enabling loose coupling and asynchronous processing","A pattern only for testing UIs","A UI pattern for user events"],1,"EDA: event broker (Kafka, RabbitMQ) decouples producers and consumers, enabling async scalable processing.","medium");
q(6,29,"The CAP theorem states that a distributed data store can provide at most two of:",["Cost, Accuracy, Performance","Consistency (all nodes see same data), Availability (every request gets a response), Partition Tolerance (system operates despite network partitions)","Concurrency, Atomicity, Persistence","Compression, Authentication, Privacy"],1,"CAP: since partitions are unavoidable in practice, real systems choose between CP (consistent) or AP (always available).","medium");
q(6,29,"Dependency Injection (DI) improves architecture by:",["A pattern for importing packages","Supplying object dependencies externally rather than creating them internally, reducing coupling, improving testability (injectable mocks), and enabling configuration without code changes","A database connection pattern","A build system technique"],1,"DI inverts control of dependency creation: constructor/setter/interface injection enables loose coupling and substituability.","medium");
q(6,29,"Fault tolerance in distributed architecture means:",["Never having any bugs","A system's ability to continue operating correctly even when components fail, through redundancy, failover, graceful degradation, circuit breakers, and retry mechanisms","Testing for hardware failures only","Having no single points of failure by definition"],1,"Fault-tolerant systems anticipate and handle failures: circuit breakers, bulkheads, retries, fallbacks, chaos engineering.","medium");
q(6,29,"CQRS (Command Query Responsibility Segregation) is:",["A caching strategy","An architectural pattern that separates read (Query) operations from write (Command) operations into different models, allowing independent optimization, scaling, and security for each side","A testing methodology","A version control branching strategy"],1,"CQRS: separate write model (normalized, consistent) from read model (optimized, denormalized views) – each scaled independently.","medium");
q(6,29,"A service mesh in microservices architecture is:",["The physical network connecting services","A dedicated infrastructure layer handling service-to-service communication (observability, security, traffic management) via sidecar proxies (e.g., Istio, Linkerd), transparently to the application","A shared database for all microservices","A monitoring dashboard only"],1,"Service mesh: sidecar proxies injected alongside each service handle mTLS, load balancing, circuit breaking, and distributed tracing without application code changes.","medium");

q(6,29,"The Strangler Fig pattern is used to:",["Prevent SQL injection","Incrementally migrate a legacy monolith by routing specific functionality to new microservices while the old system continues operating, until the monolith can be decommissioned","Eliminate deadlocks","Deploy rollbacks"],1,"Strangler Fig (Martin Fowler): new services intercept increasing portions of traffic alongside the monolith until it can be removed.","hard");
q(6,29,"The Saga pattern for distributed transactions manages consistency by:",["Using a SQL transaction spanning multiple databases","Orchestrating a sequence of local transactions each publishing events to trigger the next step, with compensating transactions to undo completed steps on failure","Managing SQL database rollbacks","A data replication strategy"],1,"Saga: no global ACID transaction across services; instead, each service does a local transaction and compensates on failure.","hard");
q(6,29,"The key architectural difference between REST and GraphQL APIs is:",["REST is always faster","REST exposes multiple fixed-structure endpoints (causing over/under-fetching); GraphQL exposes a single endpoint where clients specify exactly the data shape needed, eliminating over/under-fetching","GraphQL is not an API standard","REST requires XML; GraphQL requires JSON"],1,"GraphQL gives clients control over the exact data returned in a single query; REST's fixed endpoints often return too much or require multiple round trips.","hard");
q(6,29,"Horizontal sharding vs. vertical partitioning of databases:",["No difference – both split databases the same way","Horizontal sharding distributes rows of a table across multiple database instances by a shard key; vertical partitioning splits different columns or table groups across separate databases based on access patterns","Horizontal sharding splits tables; vertical splits rows","Vertical partitioning is only for NoSQL"],0,"Sharding: rows distributed across DB instances (e.g., UserID mod N). Vertical partitioning: different column groups in separate DBs (e.g., user profile vs. orders in separate databases).","hard");
q(6,29,"An architecture fitness function is:",["A mathematical function optimizing code complexity","An automated objective measure that evaluates architectural characteristics (performance, security, scalability) against defined thresholds, providing continuous feedback on whether architectural goals are met as the system evolves","A UML diagram for architecture review","A project management metric"],1,"Fitness functions (Neal Ford et al.): automated tests for architectural goals (e.g., 'no service >200ms', 'no direct DB calls from UI') integrated into CI/CD pipelines.","hard");

// topic 30 – Requirements Engineering  (7E 8M 5H)
q(6,30,"Requirements Engineering is:",["Writing code based on design specifications","A systematic process of eliciting, analyzing, documenting, validating, and managing requirements for a software system","Testing software against user needs","Designing database schemas"],1,"RE is the disciplined process of capturing and managing what a software system must do and the constraints under which it must operate.","easy");
q(6,30,"A functional requirement specifies:",["System performance characteristics","What the system must DO – a specific behavior, function, or service the system must provide","System physical constraints","Interface design details only"],1,"Functional requirements define system behaviors: 'The system shall allow users to log in with email and password.'","easy");
q(6,30,"A non-functional requirement (quality attribute) specifies:",["A requirement that cannot be implemented","HOW WELL the system performs a function – quality attributes like performance, security, reliability, usability, and scalability","A rejected requirement","A non-functional module"],1,"NFRs: 'The system shall respond to searches within 1 second' (performance), '99.9% availability' (reliability).","easy");
q(6,30,"A use case in requirements engineering describes:",["The database design","A scenario of interaction between an actor and the system that achieves a specific goal, defining functional requirements from the user's perspective","The implementation code","The system architecture"],1,"A use case captures a complete interaction scenario between an actor and the system leading to a meaningful outcome.","easy");
q(6,30,"SMART requirements must be:",["Simple, Modular, Accurate, Reliable, Testable","Specific, Measurable, Achievable, Relevant, Testable (or Time-bound)","Structured, Modular, Abstract, Reusable, Traceable","Scalable, Maintainable, Adaptable, Readable, Testable"],1,"SMART: Specific (unambiguous), Measurable (verifiable), Achievable (feasible), Relevant (necessary), Testable.","easy");
q(6,30,"A stakeholder in requirements engineering is:",["Only the project sponsor","Any person, group, or organization that has an interest in or is affected by the software system – including users, customers, developers, regulators, and anyone impacted","Only the end users","Only the development team"],1,"Stakeholders: all parties with a stake in the system – users, management, customers, development team, regulatory bodies.","easy");
q(6,30,"Requirements elicitation is:",["Writing requirements documents","The process of discovering, gathering, and understanding requirements from stakeholders through interviews, workshops, observation, questionnaires, and prototyping","Reviewing requirements for correctness","Prioritizing requirements"],1,"Elicitation discovers what stakeholders need via interviews, focus groups, observation, document analysis, and prototyping.","easy");

q(6,30,"The Requirements Traceability Matrix (RTM):",["Shows project team responsibilities","Maps requirements to their sources, design artifacts, test cases, and code components – enabling coverage verification and change impact analysis","Is a performance test matrix","Is a risk assessment matrix"],1,"RTM traces each requirement forward (to tests and code) and backward (to stakeholder needs), ensuring completeness and supporting change management.","medium");
q(6,30,"Functional vs. non-functional requirements differ in testability in that:",["NFRs cannot be tested","Functional requirements are tested against specific inputs/outputs; NFRs are tested against measurable quality criteria (load tests for performance, penetration tests for security, MTBF for reliability)","Functional requirements cannot be measured","They are tested identically"],1,"FRs: behavioral tests. NFRs: quality metric tests (performance benchmarks, security scans, availability measurements).","medium");
q(6,30,"MoSCoW prioritization categorizes requirements as:",["A method to eliminate requirements","Must have (critical), Should have (important), Could have (desirable), and Won't have (deferred) – used to manage scope and prioritize releases","A technique for grouping similar requirements","A method to assign requirements to team members"],1,"MoSCoW: Must (system fails without them), Should (high value), Could (enhances experience), Won't (deferred to future release).","medium");
q(6,30,"A requirements baseline is:",["The initial draft of requirements","A formally approved version of requirements agreed upon by stakeholders, serving as the reference for development; any changes go through change control","The minimum set of requirements","The final tested requirements"],1,"A baselined requirement is frozen for development; changes require formal impact analysis, stakeholder approval, and documentation.","medium");
q(6,30,"Use Case vs. User Story:",["They are identical","Use cases are structured narratives with pre/post conditions and alternative flows; User stories are short high-level descriptions from the user's perspective intended to prompt conversation and refined with acceptance criteria","User stories are more formal","Use cases are only for Waterfall; User stories only for Agile"],1,"Use cases: comprehensive behavioral specification. User stories: lightweight conversation starters ('As a user, I want... so that...') refined with acceptance criteria.","medium");
q(6,30,"Requirements creep (scope creep) is managed by:",["It is the natural growth of requirements managed by a change control board, formal change requests, impact analysis, and stakeholder approval before accepting new requirements","Adding too many bug fixes","Removing unnecessary requirements","A form of user testing"],0,"Scope creep control: baseline, change control board, impact analysis (cost/schedule/quality), stakeholder approval gates.","medium");
q(6,30,"Acceptance criteria are:",["Budget approval criteria","Specific, testable conditions that must be met for a feature or user story to be accepted by the product owner/customer – they translate requirements into verifiable conditions","Criteria for accepting new team members","Performance benchmarks only"],1,"Acceptance criteria define the 'done' boundary for each feature: precise, testable conditions derived from requirements.","medium");
q(6,30,"Joint Application Development (JAD) is:",["A programming methodology","A structured requirements elicitation technique bringing together users, IT professionals, and management in intensive facilitated workshops to collaboratively define requirements","A testing methodology","A project scheduling technique"],1,"JAD workshops: all stakeholders in facilitated sessions, collaboratively defining requirements – faster than sequential individual interviews.","medium");

q(6,30,"IEEE 830 defines good requirements as having which quality characteristics?",["Short, simple, cheap","Complete, correct, consistent, unambiguous, verifiable, modifiable, and traceable","Informal, flexible, brief","Technical, formal, lengthy"],1,"IEEE 830: good requirements are complete, correct, consistent, unambiguous, verifiable, modifiable, and traceable.","hard");
q(6,30,"In requirements language, 'shall' vs. 'should':",["No practical difference","SHALL (MUST) denotes a mandatory requirement; SHOULD denotes a desirable but optional requirement. Mixing them creates contractual and verification ambiguity about which requirements are acceptance conditions","SHOULD is stronger than SHALL","SHALL is used only for performance requirements"],0,"SHALL = mandatory (testable acceptance condition); SHOULD = optional (nice-to-have). Precise modal verbs prevent contractual disputes.","hard");
q(6,30,"Formal specification in requirements engineering uses:",["UML diagrams only","Mathematical notation and formal languages (Z, VDM, Alloy, TLA+, OCL) to specify requirements with precise unambiguous semantics, enabling automated analysis and proof","Writing requirements in a structured template","Informal stakeholder interviews"],1,"Formal specification eliminates ambiguity via mathematical semantics; enables model checking but requires mathematical expertise.","hard");
q(6,30,"The 'wicked problems' concept in requirements engineering means:",["Problems with unclear syntax in requirements documents","Problems that cannot be fully defined before solving because understanding evolves as solutions are explored – characteristic of complex social/organizational systems, justifying iterative approaches","Problems caused by poor requirements templates","Security vulnerabilities in requirements tools"],0,"Wicked problems: stakeholders often cannot fully articulate requirements until they see a partial solution – a core motivation for Agile iterative development.","hard");
q(6,30,"Requirements volatility refers to:",["Requirements that are very stable and never change","The inherent tendency of requirements to change throughout a project; architectures should favor flexibility through abstraction, loose coupling, and modular design so that changes are localized rather than systemic","A testing metric for changing test cases","A measure of stakeholder engagement"],1,"Requirements will change; good architecture encapsulates likely-to-change areas so the impact of change is contained rather than rippling through the whole system.","hard");

// ─────────────────────────────────────────────────────────────
// Validation
// ─────────────────────────────────────────────────────────────
const counts = {};
Q.forEach(q => {
  const key = `${q.sid}-${q.tid}-${q.diff}`;
  counts[key] = (counts[key] || 0) + 1;
});

const topics = [
  [3,11],[3,12],[3,13],[3,14],[3,15],
  [4,16],[4,17],[4,18],[4,19],[4,20],
  [5,21],[5,22],[5,23],[5,24],[5,25],
  [6,26],[6,27],[6,28],[6,29],[6,30]
];

let valid = true;
topics.forEach(([s,t]) => {
  const e = counts[`${s}-${t}-easy`] || 0;
  const m = counts[`${s}-${t}-medium`] || 0;
  const h = counts[`${s}-${t}-hard`] || 0;
  const total = e + m + h;
  const ok = e === 7 && m === 8 && h === 5 && total === 20;
  if (!ok) { valid = false; console.error(`FAIL S${s} T${t}: E=${e} M=${m} H=${h} Total=${total}`); }
  else console.log(`OK   S${s} T${t}: E=${e} M=${m} H=${h} Total=${total}`);
});

console.log(`\nTotal questions: ${Q.length}`);
if (!valid) { console.error("Distribution INVALID"); process.exit(1); }
console.log("Distribution VALID");

function esc(s) { return s.replace(/'/g, "''"); }

const lines = Q.map(r =>
  `INSERT INTO questions \n(subject_id, topic_id, question, options, correct_answer, explanation, difficulty) \nVALUES \n(${r.sid}, ${r.tid}, \n'${esc(r.question)}',\n'${esc(JSON.stringify(r.options))}',\n${r.ans},\n'${esc(r.explanation)}',\n'${r.diff}');`
);

fs.writeFileSync(path.join(__dirname, "seed_400.sql"), lines.join("\n\n"), "utf8");
console.log(`\nWrote seed_400.sql  (${lines.length} statements)`);
